import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAP: [CaseTemplate] = [restaurantTipSkim, texterCrash, dogInHotCar, fakeLandscaper, foundPhoneSold, waterTowerClimb, selfCheckoutBanana, holidayInflatables, funeralScene, diveBarShooting, schoolZoneCrash, homeInvasionBurglary, carjackingRobbery, apartmentFire, parkingLotAbduction, festivalOverdose, poisonCoffee, fatalPunchParty, wrenchAssault]

    static let restaurantTipSkim = SmallCases.make(
        key: "story.restaurantTipSkim",
        category: .property,
        headlines: ["Server Accused of Pocketing Shared Tip Jar Cash", "Restaurant Owner Says Tips Were Short for Months"],
        law: "misdLarceny",
        spec: "Stole $410 in shared tips belonging to {V}, a restaurant's staff, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "A restaurant's servers pool their cash tips in a jar and split them at closing. After weeks of short splits, the owner, {V}, installed a camera over the jar. On {DATE} it showed {D}, a server, folding bills into an apron pocket three times during a shift. {DL} says the cash was {D.his} own tips from a table that paid cash.",
        state: [E(.video, 3, "Jar Camera", "{D} folds bills into an apron pocket three times during the shift."), E(.document, 2, "Tip Log", "The jar's total was $410 short of the card tips by closing.")],
        defense: [E(.statement, 1, "Own Tips", "{DL} says the cash came from {D.his} own cash table.")],
        role: "Restaurant owner",
        exam: [.direct("Why did you put a camera over the tip jar?", "\"Our servers pool cash tips in a jar and split them at closing. For weeks the splits had come up short, so I mounted a camera above the jar.\""), .direct("What did the camera show on {DATE}?", "\"It showed {D}, one of our servers, folding bills from the jar into an apron pocket three separate times during one shift.\""), .direct("How much was missing from the jar that night?", "\"The count came up $410 short compared with what the register and the servers' own tallies suggested the jar should hold.\""), .direct("How does the tip pool work at your restaurant?", "\"Servers drop their cash tips into a jar behind the bar. At closing we count the jar with two servers watching and divide it by hours worked.\""), .direct("What led you to install the camera?", "\"For several weeks the splits came out lower than the card tips suggested. I mounted a small camera over the jar so I could see what was happening.\""), .direct("What did you do after you saw the footage?", "\"I watched it twice, wrote down the times, and called a manager over to watch it with me. I then called {D.him} in to talk.\""), .cross("{D} says some of that cash was {D.his} own tips from a table that paid cash, doesn't {D.he}?", "\"That is what {D.he} says. A cash table could explain some money, but I did not see the cash go into the jar before it came out.\""), .cross("The tips were counted at closing with the other servers, weren't they?", "\"Yes, everyone counted together at closing. That is how we do it every night, and {D.he} was part of that count.\""), .cross("Can you say which bills in the apron belonged to which server?", "\"No. Bills are bills. I can only tell you what the camera showed going from the jar to the pocket.\""), .cross("Did the defendant deny taking cash from the jar?", "\"{D.He} said the cash was {D.his} own from a table that paid in bills. I had no record of that table, so I couldn't confirm it.\""), .cross("Could someone have put cash into the jar and then taken it back out?", "\"It happens when a server makes a mistake in the rush. But the footage shows folding and pocketing three times, not one slip.\"")],
        theory: ("{D} skimmed the shared tip jar.", "A server with personal cash tips in an apron."),
        allocution: "\"I took what I thought I was owed, and I see now that I handled it the wrong way. I had a table that paid cash, and I'd put that money in the jar by mistake during a rush, and I took it back out when I realized. I wasn't hiding anything. I'm sorry to my coworkers.\"",
        truths: ("{DL}'s apron held $400 in small bills when searched.", "A second server admitted she had been taking from the jar for a month."),
        defendant: [.direct("Walk us through what you took from the jar.", "\"I took my own tips. I had a table that paid in cash and I had put that money in the jar when I should have kept it.\""), .direct("Why was your money in the shared jar?", "\"I dropped it in by mistake during a rush, and I took it back out when I realized. I wasn't hiding anything.\""), .direct("Did you take other servers' money?", "\"No. I would never take what belonged to someone else. I only took back what I had put in.\""), .direct("Describe the table that paid in cash in your own words.", "\"A group of four tipped in cash on the table. I put the bills in my apron to count later and mixed them up during a rush.\""), .direct("Why did you fold bills into your pocket three times?", "\"I was making change for the cash table and moving my own bills out of the jar. I didn't think anyone was watching.\""), .direct("What did you do when the owner asked about it?", "\"I told the owner the same thing, that I'd taken my own tips. I offered to count my apron in front of everyone.\""), .cross("The camera shows you doing it three times. Why three?", "\"It was a busy shift, and I was moving the money back as I had a chance. I wasn't counting how many times.\""), .cross("The jar came up $410 short that night. Where did that money go?", "\"I don't know. I did not take $410. I can only tell you what I took, and that was my own.\""), .cross("Why not tell the owner you had put cash in by accident?", "\"I own that. I figured I would sort it out at closing, and I did not think a few bills would be a problem.\""), .cross("You didn't mention the cash table to any other server that night. Why not?", "\"I didn't think of it as unusual. We all carry our own tips in our aprons, and I didn't think anyone would question it.\""), .cross("Did anyone else handle the tip jar that night?", "\"The other server and the bartender both put tips in it. I didn't count it, and I don't know who did.\"")],
        openings: ("For weeks the shared tip jar came up short. Then the owner put a camera over it, and on {DATE} it showed {D} folding bills into an apron pocket three times, on a night the jar was $410 short.", "{D} had a table that paid in cash and mixed up where those bills went. The defense will show a server who took back {D.his} own tips, not a thief skimming from coworkers."),
        closings: ("Three times in one shift, the camera shows cash going from the jar to an apron pocket, and the jar ended the night $410 short. Servers do not usually need to fold other people's money into a pocket.", "A cash table, a busy shift, and a few bills moved by someone who thought they were {D.his} own. The State has shown a motion on video, not that the money belonged to anyone else."),
        timeline: [(-30, "Short splits begin."), (0, "The camera records three pocketings."), (1, "{V} reviews the footage.")],
        identified: "The owner's jar camera.",
        impact: "We split tips to keep our cooks and our line staff, and it only works if everybody trusts the jar. Weeks of short splits hurt every one of us, and the people who earn the least felt it most. I put a camera up because I had no other way to find out. I hated having to do it.",
        genders: ["D": .female])

    static let texterCrash = SmallCases.make(
        key: "story.texterCrash",
        category: .traffic,
        headlines: ["Driver Looking at Phone Drifted Into Ditch, Hit Mailbox", "Reckless Driving Charge After Texting Crash"],
        law: "recklessDriving",
        spec: "Drove a motor vehicle on a highway carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...50,
        victim: false,
        summary: "A driver's car drifted across the center line, into a ditch, and through a mailbox on {DATE}. {D} told the trooper {D.he} had swerved for a deer. A trooper found {DL}'s phone open to a half-written text. The phone's records showed a message sent 14 seconds before the crash. {DL} says the phone was in the passenger seat.",
        state: [E(.digital, 3, "Phone Records", "A text sent 14 seconds before the crash."), E(.document, 2, "Crash Report", "Skid marks absent; the car left the road at 52 mph.")],
        defense: [E(.statement, 1, "Deer", "{DL} says a deer ran out and the swerve caused the crash.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What did you find at the scene of the crash?", "\"The car had drifted across the center line, into a ditch, and through a mailbox. There were no skid marks on the pavement before it left the road.\""), .direct("What did you see on {D}'s phone?", "\"It was open on the console to a half-written text message. Phone records showed a message sent fourteen seconds before the crash.\""), .direct("What did the defendant tell you about the cause?", "\"{D} said {D.he} swerved to avoid a deer. I looked along the road and the shoulder and found no hair, no tracks, and no sign of a deer.\""), .direct("What did the roadway look like where the car left the pavement?", "\"A straight stretch with a slight rise. The car left the road at about 52 mph, and I found no skid marks at all.\""), .direct("Where did the car end up?", "\"In a drainage ditch beside a mailbox, which the car had taken out. The airbags had deployed and the driver was awake and talking.\""), .direct("How did you determine the timing of the text?", "\"I got the carrier's records. A message was sent 14 seconds before the crash data's time stamp for impact.\""), .cross("{D} says the phone was in the passenger seat, doesn't {D.he}?", "\"That is what {D.he} told me. When I arrived, the phone was open and sitting in the console, not on the passenger seat.\""), .cross("Isn't it true you can't prove a deer wasn't there?", "\"I can only say I found no evidence of one. Deer leave very little behind if they do not get hit, so I cannot rule it out entirely.\""), .cross("If the driver braked for a deer, wouldn't you expect skid marks?", "\"Often, yes, but not always, especially with anti-lock brakes. The absence of marks is one fact I noted, and not the only one.\""), .cross("Did anyone else see the crash or a deer near the road?", "\"No. I canvassed two nearby houses and nobody saw anything, including any deer.\""), .cross("Could the 14-second gap have been a delayed send rather than someone typing?", "\"It's possible that a message queued earlier went out at that moment. I can't say who or whether anyone was touching the phone.\"")],
        theory: ("{D} was texting and left the road at 52 mph.", "A driver who swerved for a deer."),
        allocution: "\"I was texting, and I'm sorry I hit the mailbox. I told the trooper about a deer because I was scared and embarrassed. I know how dangerous it was to look at a phone while driving. I'm grateful nobody was hurt, and I'll pay for the mailbox and ditch, and keep my phone out of reach.\"",
        truths: ("The phone's screen was unlocked and the keyboard open at impact.", "A neighbor's camera showed a deer crossing 400 feet earlier."),
        defendant: [.direct("What happened on the road that night?", "\"I was driving at a normal speed when an animal ran into the road. I swerved hard and lost control, and the car went off into the ditch.\""), .direct("Were you using your phone?", "\"No. The phone was not in my hand. I was watching the road, and I did not send a message while I was driving.\""), .direct("Where was the phone before the crash?", "\"I believed it was in the passenger seat. After the crash, things were scattered, and I'm not surprised it ended up somewhere else.\""), .direct("How fast were you going before the crash?", "\"About fifty. It's a straight, empty road and I was watching the speedometer at the speed limit.\""), .direct("Walk us through what you saw just before the car left the road.", "\"A deer stepped out of the trees on the right side. I yanked the wheel left, crossed the center line, and lost control.\""), .direct("Where was your phone at the time?", "\"On the passenger seat, face down. After the crash it was on the floor, open to a screen I didn't recognize.\""), .cross("Phone records show a message sent fourteen seconds before the crash. Can you explain that?", "\"I can't. I do not remember sending anything. I know what the records say, but I did not think I was texting.\""), .cross("The trooper found no deer, no tracks, and no skid marks. Is that right?", "\"That is what the trooper says. I know what I saw, and I swerved. I did not have time to brake.\""), .cross("The text on the phone was half-written. Who was writing it?", "\"I do not know who started it. It might have been from earlier. I just know I was not typing when I drove off the road.\""), .cross("You didn't see the deer again after the crash. Where did it go?", "\"It ran off into the woods. I didn't look for it, because I was shaken and bleeding from a cut on my head.\""), .cross("The trooper found no tracks and no deer. Is that something you can explain?", "\"I can't. It was dark and the shoulder was gravel, so I don't know what would leave a track.\"")],
        openings: ("A car crossed the center line, went into a ditch, and took out a mailbox. A trooper found no skid marks, no sign of a deer, and a phone open to a half-written text sent fourteen seconds before the crash.", "{D} swerved for a deer on a dark road and lost control. The defense will show that a swerve leaves few marks and that the State cannot prove who touched the phone."),
        closings: ("No skid marks, no deer, a phone open on the console, and a message sent fourteen seconds before impact. The simplest explanation is the one in the phone records.", "A deer can cross a road and leave nothing behind. The State can show a phone and a timestamp, but not who typed or that this was careless driving."),
        timeline: [(0, "4:10 p.m.: a text is sent."), (0, "4:10 p.m.: the car leaves the road."), (0, "4:30 p.m.: the trooper arrives.")],
        identified: "A trooper's crash investigation.")

    static let dogInHotCar = SmallCases.make(
        key: "story.dogInHotCar",
        category: .publicOrder,
        headlines: ["Dog Left in Parked Car on 94-Degree Afternoon", "Customers Break Window to Free Panting Dog"],
        law: "animalCruelty",
        spec: "Intentionally deprived an animal, a dog, of necessary shelter and relief from heat, on {DATE}.",
        ages: 19...60,
        victim: false,
        summary: "Customers at a grocery store on {DATE} saw a dog panting in a closed car with the windows cracked an inch in 94-degree heat. After twenty-two minutes, two customers broke a rear window and a deputy took the dog to a veterinarian. {D} came out with groceries and said the dog 'was only there for a few minutes.' {DL} says the engine ran with the air conditioner on.",
        state: [E(.video, 3, "Store Camera", "The car sits with the dog inside for 22 minutes; the engine is off."), E(.document, 2, "Veterinary Report", "Heat exhaustion; body temperature 106 degrees.")],
        defense: [E(.statement, 1, "Air Conditioner", "{DL} says the engine was running with the A/C on.")],
        role: "Animal control officer",
        exam: [.direct("How did you get involved?", "\"Customers at a grocery store called us on {DATE} about a dog panting in a closed car. I arrived within minutes of the 2:27 call.\""), .direct("What condition was the dog in?", "\"Heavily panting and weak, with drool, in 94-degree heat. The dog's body temperature at the vet was 106 degrees, which is dangerous.\""), .direct("What did the car look like?", "\"A closed car with the windows cracked about an inch. The interior was hot to the touch when I put a hand on the roof.\""), .direct("How long was the dog in there?", "\"The store camera shows 22 minutes from when {D} parked at 2:05 until customers broke a rear window at 2:27.\""), .direct("What did {D} say?", "\"When {D.he} came out with groceries, {D.he} said the dog was only in there for a few minutes. {D.He} also said the engine was running.\""), .direct("What did the vet find?", "\"Heat exhaustion. The dog was treated with cooling and fluids and recovered. The vet said another few minutes could have been fatal.\""), .cross("Isn't it true the dog survived?", "\"Yes, it recovered. That doesn't change the danger it was in during those 22 minutes.\""), .cross("Did the car's windows stay cracked?", "\"Yes, about an inch each, front and rear. That helps a little but does little in 94-degree heat.\""), .cross("Did you check whether the engine was running?", "\"I wasn't there until after the window was broken. I couldn't tell you whether the engine was running before.\""), .cross("What does the camera show about the engine?", "\"The car sits still, and no brake lights come on. I can't see the exhaust, so I'm relying on that and on the owner's key.\""), .cross("Did the customers who broke the window act in good faith?", "\"They did, and I told them they did the right thing. But I had no way to tell what happened before they called.\"")],
        theory: ("{D} left a dog in a closed car for 22 minutes in the heat.", "A dog with the air conditioner running."),
        allocution: "\"I didn't think it was that long, and I'm sorry. I meant to make a quick grocery run, and I left the engine running with the air on and the windows cracked, and I thought that would keep the car cool. I love that dog. I'll never leave an animal in a car again.\"",
        truths: ("{DL}'s car had no remote starter and the key was in {D.his} pocket.", "The store camera showed the car's brake lights off the whole time."),
        defendant: [.direct("Why was your dog in the car?", "\"I was making a quick grocery run and thought it would be a few minutes. The dog was fine in the car on many other trips.\""), .direct("Was the air conditioner on?", "\"Yes. I left the engine running with the A/C on and the windows cracked. I thought that would keep the car cool.\""), .direct("How long were you in the store?", "\"I thought it was about ten minutes. The line at the register was long, and I lost track of time.\""), .direct("What did you see when you came out?", "\"A crowd and a broken window. I was shocked and upset, and I said the dog was only in there for a few minutes.\""), .direct("How is the dog now?", "\"Home and healthy. The vet said it's fine, and I haven't left the dog in the car since.\""), .direct("What would you do differently?", "\"I'd leave the dog at home on a day like that. I should have thought about the heat.\""), .cross("The store camera shows 22 minutes, doesn't it?", "\"If the camera says 22, I accept it. I didn't have a watch on me, so I don't argue with the time.\""), .cross("Does your car have a remote starter?", "\"No. It doesn't have a remote starter, and the key goes with me. I know that makes it hard to say the engine stayed on.\""), .cross("The brake lights were off the entire time?", "\"I'm told so. I didn't watch from inside the store, and I can't explain it.\""), .cross("You knew it was 94 degrees?", "\"I knew it was a hot day. I didn't check the exact number. In hindsight, yes.\""), .cross("You said it was only a few minutes, but it was over twenty?", "\"I told them what I believed in the moment. I was wrong about the time, and I know I shouldn't have said it.\"")],
        openings: ("On a 94-degree day, {D} parked at a grocery store at 2:05, left a dog in a closed car with the windows open an inch, and was gone for 22 minutes. Customers broke a window to get the dog out, and the vet found a body temperature of 106 degrees.", "{D} says the engine was running with the air conditioner on and expected to be inside for only minutes. The defense says the dog was kept cool, and the State cannot prove the dog was in the heat as it claims."),
        closings: ("The store camera does not lie: 22 minutes, no brake lights, a car with an inch of window, and a dog at 106 degrees. {D} said a few minutes, and the video says otherwise.", "The dog recovered, the windows were cracked, and {D} says the air conditioner was running. Without proof that the engine was off, the State has not shown {DL} knowingly exposed the animal to danger."),
        timeline: [(0, "2:05 p.m.: {DL} parks and goes in."), (0, "2:27 p.m.: customers break the window."), (0, "2:40 p.m.: the dog reaches the vet.")],
        identified: "Customers' call and the store camera.",
        mood: .wantsConviction)

    static let fakeLandscaper = SmallCases.make(
        key: "story.fakeLandscaper",
        category: .whiteCollar,
        headlines: ["Landscaper Took $1,800 Deposit and Never Showed", "Homeowner Says Business Phone Went Dead"],
        law: "falsePretenses",
        spec: "Obtained $1,800 from {V} by falsely representing that {D} would perform landscaping work, on {DATE}.",
        ages: 24...58,
        victim: true,
        summary: "{V} paid {D} a $1,800 deposit on {DATE} for a retaining wall and sod. {DL} promised to start the following Monday. {D.He} never showed, stopped answering calls, and the business number was disconnected. Three other customers say the same. {DL} says {D.his} truck broke down and {D.he} planned to return the deposit.",
        state: [E(.document, 3, "Contract and Receipt", "A signed contract and a receipt for $1,800."), E(.statement, 2, "Other Customers", "Three customers paid deposits and got nothing.")],
        defense: [E(.document, 2, "Truck Repair", "A shop invoice for a transmission repair the same week.")],
        role: "Sheriff's financial crimes detective",
        exam: [.direct("What was your role in this investigation?", "\"I'm a detective with the sheriff's financial crimes unit. {V} filed a complaint, and then three other customers contacted us with the same story.\""), .direct("What did {V} describe?", "\"{V} paid {D} a $1,800 deposit on {DATE} for a retaining wall and sod, under a signed contract. {DL} promised to start the following Monday.\""), .direct("What happened on that Monday?", "\"{D.He} didn't show. {V} called and texted for a week, then found the business number disconnected. {V} reported it three weeks after paying.\""), .direct("What did the other customers say?", "\"Three other customers each paid deposits and got nothing. Their amounts were similar, and each said {D.he} stopped responding.\""), .direct("What did you find about {D}'s bank account?", "\"Records show each deposit was moved out or spent within about a week of being paid. There was little left for materials or labor.\""), .direct("What explanation did the defendant give you?", "\"{D.He} said the truck broke down and that {D.he} planned to return the deposit. {D.He} gave me a repair invoice from that same week.\""), .cross("Isn't it true the defendant had a transmission repair the same week?", "\"Yes, I saw the invoice for a transmission repair. It supports that the truck did have a problem.\""), .cross("Did the defendant do any work at all for these customers?", "\"Not for the four I spoke with. I didn't find any work done on any of those jobs.\""), .cross("Did the contract state a firm start date?", "\"The contract said work would begin the following Monday. It didn't have a penalty clause or an exact deadline beyond that.\""), .cross("Did the defendant ever refund any of the deposits?", "\"Not by the time I interviewed {D.him}. {D.He} said there was a plan to return money, but nothing had been paid back.\""), .cross("Did you speak with the defendant's business partner?", "\"I understood there was one, and that the partner left with equipment. I haven't been able to locate the partner.\"")],
        theory: ("{D} took deposits for work {D.he} never intended to do.", "A landscaper with a broken truck."),
        allocution: "\"I run a small landscaping business, and I took those deposits to buy materials, and I fully planned to start the next Monday. My truck broke down, and I got behind and didn't know how to tell people. I should have called each customer. I'll pay everyone back.\"",
        truths: ("{DL}'s account was drained within a week of each deposit.", "{DL}'s partner had run off with the equipment, a business record shows."),
        defendant: [.direct("What can you tell us about your landscaping business?", "\"I run a small landscaping and hardscape business. I do retaining walls, sod, and patios, and I've been doing it for years.\""), .direct("Why did you take {V}'s job?", "\"I wanted the work, and the deposit covered materials. I fully planned to start the following Monday.\""), .direct("What happened that week?", "\"My truck's transmission went out the weekend before the job. I had to pay for the repair, and I couldn't haul the stone.\""), .direct("Why didn't you call {V} back?", "\"I was embarrassed. I had no money and no truck, and every call I saw made me feel worse, so I let them go to voicemail.\""), .direct("What about your business partner?", "\"My partner left with some of my equipment. That was part of the problem, because I couldn't do the work without it.\""), .direct("What do you plan to do about the deposits?", "\"I want to pay them all back. I've been working odd jobs and putting money aside to refund every customer.\""), .cross("You spent the deposits within a week, didn't you?", "\"I used some for the truck and some on other costs. I'm not going to say it was all spent on {V}'s job.\""), .cross("You never started any of the four jobs?", "\"No. I took the money for all four and didn't start any of them. I let it get away from me.\""), .cross("You disconnected the business phone?", "\"Yes. I couldn't pay the bill, and I couldn't face the customers. I know that looks like I was hiding.\""), .cross("You didn't send the customers a note or a refund?", "\"I didn't. I kept thinking I'd fix things first, and that was a mistake.\""), .cross("You took the fourth deposit after the third job fell through?", "\"I was still hoping to get work done, and I thought a new job would get me out of the hole. That's not an excuse.\"")],
        openings: ("{V} signed a contract and paid {D} an $1,800 deposit for a retaining wall and sod. {DL} promised to start Monday, never showed, and shut off the business phone, and three other customers say the same thing happened to them.", "{D}'s truck transmission failed the same week, a partner ran off with the equipment, and {DL} meant to repay every customer. The defense says a business failure and broken promises are a civil problem, not a crime."),
        closings: ("Four customers, four deposits, no work, and a disconnected phone. {D}'s account was drained within a week of each payment, and a pattern like that is not bad luck.", "A transmission invoice from the same week, a partner who vanished with the equipment, and a stated plan to pay everyone back. The State must prove {D} never intended to do the work, and the evidence shows a business that collapsed."),
        timeline: [(0, "Monday: {DL} fails to show."), (7, "The business number is disconnected."), (21, "{V} reports it to deputies.")],
        identified: "{V}'s complaint and three others.",
        impact: "That deposit was our savings for the wall. We'd been putting aside a little each month for two years to fix the slope behind our house, and every rainstorm since has washed more of it away. {D.He} stopped answering our calls, and we found out others were left waiting too.",
        genders: ["D": .male])

    static let foundPhoneSold = SmallCases.make(
        key: "story.foundPhoneSold",
        category: .property,
        headlines: ["Man Sold Phone Found at Park, Owner Tracked It", "Finder Says He Never Saw the Owner's Messages"],
        law: "possStolen",
        spec: "Possessed a cellular telephone valued at $540 belonging to {V}, knowing it stolen, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V} lost a phone at a park on {DATE} and the owner's messages offered a $50 reward. {D} found it, ignored the messages, and sold it to a pawn shop the next day. {V} tracked it to the shop. {DL} says {D.he} never saw the messages and thought the phone was abandoned. The phone was worth $540.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for the phone."), E(.digital, 2, "Messages", "Four messages offering a reward, read on the phone.")],
        defense: [E(.statement, 1, "Abandoned", "{DL} says the phone was dead and appeared abandoned.")],
        role: "Pawn shop clerk",
        exam: [.direct("How did {D} come to your shop?", "\"{D} came in the day after {V} lost the phone and asked for a loan against it. I recorded {DL}'s ID and issued a pawn ticket.\""), .direct("What phone was it?", "\"A recent model in good condition, worth about $540. {D.He} took a loan for far less than its value, which is typical for pawn.\""), .direct("What condition was the phone in?", "\"Powered off and out of battery. I charged it to test it, and the screen lit up with several messages.\""), .direct("What did the messages say?", "\"Four messages offering a $50 reward for return of the phone. They were from the owner and had been read on the phone.\""), .direct("How did {V} find the phone?", "\"{V} used a phone tracker and traced it to our shop two days after the loss. {V} came in with a deputy.\""), .direct("What did you do once {V} identified it?", "\"I handed it over to the deputy with the ticket and {DL}'s ID. The shop keeps records for exactly this reason.\""), .cross("Isn't it true the defendant used a real ID?", "\"Yes. {D.He} handed over a valid license with the right address. {D.He} didn't try to hide anything.\""), .cross("Was the phone locked?", "\"It had a lock screen, and the messages showed on it when I charged it. They were readable at a glance.\""), .cross("Did the defendant say anything about finding it?", "\"{D.He} said it was found at a park and that nobody had claimed it. I didn't hear anything about the reward messages.\""), .cross("Were the messages visible when the defendant first brought it in?", "\"I don't know. The phone was dead when I got it, so {DL} may not have seen them. They only appeared after I charged it.\""), .cross("Do you take in many phones a week?", "\"Dozens. A few of them turn out to be reported lost, and our records help with those. {D.his} is not unusual.\"")],
        theory: ("{D} sold a phone {D.he} knew belonged to someone else.", "A finder who thought it was abandoned."),
        allocution: "\"I should have turned it in. I found it near a bench with a dead battery, and nobody was around, and I figured it had been left for a while. I never saw the messages offering a reward. I'm sorry to {V}, and I'll make up what the pawn shop paid me.\"",
        truths: ("The messages were marked 'read' on {DL}'s phone-charge session.", "The lock-screen message was cracked and unreadable, an examiner confirmed."),
        defendant: [.direct("How did you find the phone?", "\"I found it lying near a bench at the park. The screen was dark and the battery was dead, and no one was around.\""), .direct("Did you look for the owner?", "\"I looked around but didn't see anyone. I figured it had been left for a while, since it was dead and there was nobody nearby.\""), .direct("Did you see any messages on it?", "\"No. The phone was dead and the screen was cracked, and I never turned it on. I didn't see any messages at all.\""), .direct("Why did you take it to a pawn shop?", "\"I needed money for rent and thought a dead phone with nobody looking for it was fair to sell. I used my real ID.\""), .direct("What happened when the deputy contacted you?", "\"I told the deputy exactly where I found it and why I sold it. I felt awful when I heard about the reward messages.\""), .direct("What would you do differently?", "\"I'd have taken it to the sheriff's office. I just didn't think of the owner as someone looking for it.\""), .cross("You sold a $540 phone for a small loan, didn't you?", "\"I took what the shop offered. I wanted quick money, and I didn't think about its real value.\""), .cross("The phone was read-marked on the messages, wasn't it?", "\"That's what I'm told. I can't explain it, since I never turned the screen on myself.\""), .cross("You didn't try to find the owner or check lost and found?", "\"No, I didn't. I thought if someone cared they'd have come back to the bench.\""), .cross("You charged the phone at some point, didn't you?", "\"I plugged it in once at home to see if it worked. I don't remember reading anything, but I'll admit the charger was on.\""), .cross("The cracked lock-screen message was hard to read?", "\"It was hard to see because the glass was cracked. I could be wrong, but it didn't look like anything to me.\"")],
        openings: ("{V} lost a phone at a park, and the messages on its screen offered a $50 reward. {D} found it, read the messages, and pawned the $540 phone the next day, and {V} tracked it to the shop.", "{D} found a dead phone with a cracked screen near a park bench and thought it was abandoned. The defense says {D.he} never saw any reward message and never knew who owned it."),
        closings: ("Four reward messages were on that phone, read and unanswered, and {D} pawned it for cash the next day. {DL} knew it belonged to someone, and the choice to keep it was deliberate.", "The phone was dead, the screen was cracked, and {D} used a real ID to pawn it. The State must prove {DL} knew the phone was lost property, and a cracked screen leaves reasonable doubt."),
        timeline: [(0, "Afternoon: {V} loses the phone."), (1, "{DL} pawns it."), (2, "{V} tracks it to the shop.")],
        identified: "{V}'s phone tracker.",
        impact: "It had photos of my late mother, and I'd never backed them up. Some of them were the last pictures anyone took of her. I offered a reward and sent messages, and nobody answered. When I found it in a pawn shop, I just wanted to see the pictures again.",
        genders: ["D": .male])

    static let waterTowerClimb = SmallCases.make(
        key: "story.waterTowerClimb",
        category: .property,
        headlines: ["Teens Climb Town Water Tower for Photos, Charged With Trespass", "Deputies Find Teen at Top of Water Tower"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a municipal water tower, after being notified not to enter, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "A resident called deputies on {DATE} about people at the top of the town's water tower. {D} and two friends had climbed the ladder around the security fence, past a sign saying 'No Trespassing, Violators Prosecuted.' {DL} says the gate was open and no one told them to leave. The group reached the top at about 8 p.m., and a phone video from the top shows {DL}. The tower's gate is kept closed with a chain and a padlock, and deputies arrived at about 8:30 p.m.",
        state: [E(.physical, 3, "Sign and Fence", "A posted sign on the fence and on the ladder."), E(.video, 2, "Phone Video", "{D} at the top: 'we're on the tower!'")],
        defense: [E(.statement, 1, "Open Gate", "{DL} says the gate was open.")],
        role: "Town public works director",
        exam: [.direct("How is the water tower secured?", "\"There is a security fence around the base with a gate, and signs posted that say 'No Trespassing, Violators Prosecuted.' The gate is kept closed with a chain and padlock.\""), .direct("What was the condition of the gate when deputies arrived?", "\"It was closed with the chain and padlock when my crew last checked it. I was told the group had reached the ladder and gone up around the fence.\""), .direct("Why is it dangerous for people to climb it?", "\"It is a tall structure, the ladder is exposed, and there is a drop on all sides. A fall would be fatal, and we have a responsibility for it.\""), .direct("How many access points does the tower have, and how are they protected?", "\"One ladder runs up the leg of the tower, and it is inside a chain-link fence with a locking gate. There are signs on the fence and a second sign on the first rung of the ladder.\""), .direct("What does the sign say?", "\"'No Trespassing, Violators Prosecuted.' It is in large red letters and was replaced last spring, so it should have been legible at dusk.\""), .direct("How do you know where the group went once they were past the fence?", "\"A resident called at about 8 p.m. and I reviewed a phone video later. It shows {D} at the top of the ladder with two friends, calling out that they were on the tower.\""), .cross("Isn't it possible the chain was loose that day?", "\"I do not believe so. It was a padlock, and we check it regularly. I cannot swear what happened on the night itself.\""), .cross("Nobody was hurt, were they?", "\"Luckily, no one was hurt. The group came down and deputies met them at the base.\""), .cross("Was there a sign on the ladder as well as on the fence?", "\"There is a sign at the fence. I would have to check whether one is on the ladder itself, and I do not recall.\""), .cross("Do your crews check that gate every day?", "\"Not daily. A crew checks it on Fridays and when there is a work order, so I can't say what shape it was in on that particular evening.\""), .cross("Was anything damaged at the tower?", "\"No. The deputies found no cut chain, no broken lock, and no damage to the ladder or the tank.\"")],
        theory: ("{D} climbed a posted water tower.", "A teen who found an open gate."),
        allocution: "\"It was stupid, and I'm sorry. We walked in through a gate that was open, and nobody told us to leave. It was dark by the time I noticed any signs. I should have known better than to climb something that high. I'm sorry to the town, and I'll never do it again.\"",
        truths: ("{DL}'s friend posted 'cut the chain' in a text.", "The gate was left unlocked by a worker and a sign blown down, the director later admitted."),
        defendant: [.direct("How did you and your friends get to the top of the tower?", "\"We walked in through the gate, which was open, and started up the ladder. Nobody stopped us or told us to leave.\""), .direct("Did you see any warning signs?", "\"I saw one on the ladder after we started climbing. It was dark by then, and I wasn't paying attention to the signs on the fence.\""), .direct("Why did you go up?", "\"I was curious about the view. We had talked about it for a while, and a friend wanted to see the town from the top.\""), .direct("Who were you with, and how did the trip start?", "\"Two friends from school. We were driving around after dinner and one of us said the tower had a great view, so we parked and walked over.\""), .direct("What did the gate look like when you got there?", "\"Open, with the chain hanging. I didn't touch the lock and I didn't cut anything, and nobody told us we weren't allowed.\""), .direct("What did you do once you reached the top?", "\"We took photos and a short video. It was about thirty minutes before deputies came, and we climbed down when they called us.\""), .cross("You kept climbing after you saw the sign, didn't you?", "\"I did. I should have turned around. I let curiosity get the better of me.\""), .cross("It was a dare, wasn't it?", "\"Maybe a little. My friends were joking about it, and nobody wanted to be the one to back out.\""), .cross("The public works director says the gate was chained and padlocked. Do you dispute that?", "\"We got in without cutting anything, and the gate was open when we got there.\""), .cross("You saw the sign on the ladder and kept climbing. What was going through your mind?", "\"That we would only be up there for a few minutes and no one would care. It was a bad decision, and I understand why the sign was there.\""), .cross("You were about 100 feet up with no safety gear. Weren't you worried about falling?", "\"A little, yes. I held on tight and was nervous the whole time, but I didn't want to be the one who backed out.\"")],
        openings: ("A town water tower sits behind a fence, a posted sign, and a chained gate. On {DATE}, {D} and two friends climbed it, and a phone video from the top shows {DL} there around 8 p.m.", "{D} says the gate was open and nobody told the group to leave. The defense will show a curious teenager who walked through an opening, not someone who cut a lock."),
        closings: ("A fence, a padlock, a sign saying violators will be prosecuted, and a video from the top. {D} climbed a structure the town had clearly closed off to the public.", "The gate stood open, no one told {D} to leave, and no one was hurt. The State must show that {D.he} knew entry was forbidden, and the evidence on that point is thin."),
        timeline: [(0, "Dusk: three teens at the fence."), (0, "8 p.m.: they reach the top."), (0, "8:30 p.m.: deputies arrive.")],
        identified: "A resident's call.",
        impact: "That tower supplies the whole east side of town, and a person who climbs it can touch the hatch that guards our water. We had to bring in crews that night, and the sheriff stayed until morning. People forget how fragile something like that is. It's our drinking water.",
        genders: ["D": .male])

    static let selfCheckoutBanana = SmallCases.make(
        key: "story.selfCheckoutBanana",
        category: .property,
        headlines: ["Shopper Scanned Cheap Produce Code for Steak at Self-Checkout", "Store Says Man Did It Eleven Times"],
        law: "misdLarceny",
        spec: "Stole $94 in meat from a grocery store by scanning it as produce, on {DATE}.",
        ages: 19...65,
        victim: false,
        summary: "A grocery store's loss prevention team noticed {D} using the self-checkout on {DATE}, weighing steaks and scanning a banana code each time. The steaks rang up as $1.20 instead of $94. The store pulled records and found eleven similar visits. {DL} says the scanner mis-read the items and {D.he} never noticed.",
        state: [E(.video, 3, "Self-Checkout Camera", "{D} places steaks on the scale and taps the banana code."), E(.document, 2, "Transaction Records", "Eleven visits in three months with steak weights and banana codes.")],
        defense: [E(.statement, 1, "Scanner", "{DL} says the machine mis-read the labels.")],
        role: "Grocery store loss prevention manager",
        exam: [.direct("What did you notice at the self-checkout?", "\"On {DATE}, I saw {D} place steaks on the scale and then tap the produce screen to enter a banana code each time.\""), .direct("How much did the steaks ring up as?", "\"They rang up at $1.20 instead of $94. That's the difference between the banana price and the price of the meat.\""), .direct("What did you learn when you checked the records?", "\"We pulled the transaction records and found eleven similar visits by {DL}, all with the same pattern of meat weighed and a produce code entered.\""), .direct("What first drew your attention to {D}?", "\"A pattern. The same customer was using the same lane and entering the same produce code on items that were clearly not produce. The camera over the lane shows the steaks on the scale each time.\""), .direct("How does the self-checkout record a produce purchase?", "\"The customer taps a code on the touch screen and the scale weighs the item. The price comes from the code, so a banana code on steak weighs it as bananas.\""), .direct("How many of the eleven visits show the banana code on steak?", "\"All eleven. Each one has a steak weight between two and three pounds, and each one totals under two dollars.\""), .cross("Machines get things wrong, don't they?", "\"They do sometimes, but a machine does not misread the same way eleven separate times for the same person.\""), .cross("{D} paid for what the machine charged, didn't {D.he}?", "\"Yes, $1.20 for that transaction. {D.He} paid what the screen said, and I'll acknowledge that.\""), .cross("Did anyone at the store ever tell {D} the scanner was misreading items?", "\"No. We did not warn customers. If the scanner had a known problem, I would want to look at that more closely.\""), .cross("Does the machine ever select the wrong code on its own?", "\"It can happen if someone bumps the screen, but the code is entered by touch and can't be repeated eleven times by accident.\""), .cross("Did the defendant try to hide the steaks or leave quickly?", "\"{D.He} walked out through the main door and did not appear to hurry. We stopped {D.him} in the entrance, and {D.he} came back inside without argument.\"")],
        theory: ("{D} scanned steaks as bananas.", "A scanner that mis-read the labels."),
        allocution: "\"I'll repay the store. I tapped what looked right on the produce screen, and I never noticed the steaks ringing up so low. I shop there often and buy steak for dinner, and I'd never intentionally cheat them. I'm sorry for any loss, and I'll pay the difference.\"",
        truths: ("{DL} told a friend 'steak for a buck.'", "The store's scanner had been mis-reading produce codes that month, an engineer confirmed."),
        defendant: [.direct("Did you tap in a banana code at the self-checkout?", "\"I tapped what was on the screen. The produce screen came up and I picked the item that looked right.\""), .direct("Why were you buying steak?", "\"Because I like steak, and I shop at that store a lot. Steak is what I usually buy for dinner.\""), .direct("Did you notice the price on the screen?", "\"I did not look closely. I figured the machine knew what it was doing. I just paid and left.\""), .direct("How often do you shop at that store?", "\"Two or three times a week, usually after work. I buy the same few things and use self-checkout because it's quicker.\""), .direct("What do you remember about the day you were stopped?", "\"I checked out the steaks and a few other items and walked toward the door. A manager asked me to come back inside and showed me the screen.\""), .direct("Did you ever look at the total on the screen?", "\"Not closely. I tapped pay and took the receipt without checking it, and it was always a small number because I bought little.\""), .cross("You came in eleven times and the steak always rang up for $1.20?", "\"I shop often, and I did not pay attention to totals. If the machine charged me that little, I did not think about it.\""), .cross("$1.20 for $94 worth of steak. Didn't that seem strange?", "\"In hindsight, yes. At the time I was not paying attention. I'm not proud of how I handled it.\""), .cross("You picked the banana code every time, didn't you?", "\"I picked what looked right on the screen. I do not remember choosing the banana code on purpose.\""), .cross("The total was $1.20 for several pounds of steak. Didn't that look wrong to you?", "\"It should have. I never paid attention to how the totals came out, and I know that sounds odd.\""), .cross("You came in eleven times in three months with the same steak total. How is that a coincidence?", "\"I shop there a lot and buy the same cuts, so it's not surprising that I had the same items. I never meant to choose the wrong code.\"")],
        openings: ("On {DATE}, a store loss prevention team watched {D} weigh steaks at self-checkout and enter a banana code, so $94 in meat rang up at $1.20. The records show eleven similar visits.", "Jurors will hear that a self-checkout scanner can misread codes and that {D} paid what the screen asked. {D.He} never noticed, and no one proved otherwise."),
        closings: ("Eleven visits, steak every time, a banana code every time, and a total of $1.20. That is not what bad luck looks like. It looks like a habit.", "A machine rang up what it rang up, and {D} paid it. The State asks you to assume that {D.he} chose the wrong code on purpose, eleven times. That assumption is not proof."),
        timeline: [(-90, "The first banana-code visit."), (0, "Loss prevention watches the lane."), (0, "{DL} is stopped at the door.")],
        identified: "Loss prevention's transaction review.",
        genders: ["D": .male])

    static let holidayInflatables = SmallCases.make(
        key: "story.holidayInflatables",
        category: .property,
        headlines: ["Lawn Inflatables Vanish From Three Yards Before Christmas", "Man Seen Loading Inflatable Snowman Into Truck"],
        law: "misdLarceny",
        spec: "Stole lawn decorations valued at $340 belonging to {V}, on {DATE}.",
        ages: 18...55,
        victim: true,
        summary: "Three neighbors lost lawn inflatables in a December week, including {V}'s nine-foot Santa and a snowman, valued at $340. A neighbor's camera showed {D}'s truck at {V}'s yard at 3 a.m. Deputies found two inflatables in {DL}'s garage. {DL} says {D.he} found them at a curb and was saving them for a sale.",
        state: [E(.video, 3, "Neighbor's Camera", "A truck stops at {V}'s yard and a man loads an inflatable at 3 a.m."), E(.physical, 2, "Inflatables", "Two inflatables with {V}'s name written on the tags.", .search)],
        defense: [E(.statement, 1, "Curb", "{DL} says the inflatables were at a curb.")],
        role: "Sheriff's deputy",
        exam: [.direct("What was reported on the morning after?", "\"{V} found {V.his} nine-foot Santa and a snowman gone from the yard. Two other neighbors also reported missing lawn inflatables that same week.\""), .direct("What was the total value?", "\"{V}'s two inflatables were worth $340. The other two neighbors lost decorations as well.\""), .direct("What did the neighbor's camera show?", "\"At 3 a.m. a truck stops at {V}'s yard, and a person gets out and loads an inflatable into the bed before driving off.\""), .direct("What did you find at {D}'s home?", "\"Four days after the theft, I found two inflatables in {D}'s garage, with {V}'s name written on the tags.\""), .direct("How did {V} identify them?", "\"By the name on the tag and a specific patch on the Santa's coat. {V} was relieved to see them.\""), .direct("What did the defendant say about them?", "\"{DL} said they were found at a curb and that {D.he} was saving them to sell later.\""), .cross("Isn't it true you can't see the person's face on the video?", "\"That's correct. The camera shows the truck and a figure loading the item, but the image is dark and the face is not visible.\""), .cross("Did the defendant say where the curb was?", "\"Vaguely. {DL} said it was near a house on a back road, and I couldn't find anyone who could confirm that.\""), .cross("Did you find the third neighbor's inflatables in the defendant's garage?", "\"No. Only two were found, both {V}'s. The other neighbor's decorations weren't recovered.\""), .cross("Did the defendant hide the inflatables?", "\"They were in the garage and not covered. {D.He} showed me when I asked.\""), .cross("Did a teenager come forward about this?", "\"I heard that a teenager might have been involved, but nobody has given me a statement. I can't say what that person did.\"")],
        theory: ("{D} took holiday decorations from three yards.", "A curb find and a resale plan."),
        allocution: "\"I found those two inflatables deflated beside a trash pile at a curb a few days before the deputy came, and they looked like free stuff someone was throwing out. I thought I could sell them at a yard sale. I'm sorry to the neighbors. I'll pay everyone back.\"",
        truths: ("{DL}'s truck was on camera at all three yards.", "A teenager admitted taking the inflatables and leaving them where {DL} found them."),
        defendant: [.direct("Where did you get the inflatables?", "\"I found them at a curb a few days before the deputy came. They were deflated and sitting by a trash pile.\""), .direct("Why did you take them?", "\"They looked like free stuff someone was throwing out, and I thought I could sell them at a yard sale.\""), .direct("Did you notice a name on the tags?", "\"I saw writing, but I didn't read it closely. I thought it was a regular store tag.\""), .direct("Were you on {V}'s street at 3 a.m.?", "\"I was out that night in my truck. I do drive around late at times, but I didn't take anything from {V}'s yard.\""), .direct("What did you tell the deputy?", "\"I showed the inflatables and said where I'd found them. I wasn't trying to hide anything, and the garage was open.\""), .direct("What would you say to {V}?", "\"I apologize. I wouldn't have picked them up if I'd known they were stolen. I'd have returned them right away.\""), .cross("Your truck was on camera at all three yards, wasn't it?", "\"I'm told so. I do drive that route sometimes, but I didn't stop and take anything from any of them.\""), .cross("The tags had {V}'s name on them?", "\"Yes, I'm told. I didn't look carefully, and I know that's a hard thing to believe.\""), .cross("You were planning to sell them?", "\"Yes. I figured I'd put them in a yard sale and make a few dollars. I should have asked around first.\""), .cross("You can't tell us exactly where the curb was?", "\"I recall a road near the edge of town, but I can't point to the house. I know that doesn't help.\""), .cross("Isn't it a coincidence that you found inflatables just like those missing?", "\"I understand it sounds suspicious. All I can say is how I got them, and I didn't take them from any yard.\"")],
        openings: ("During one December week, three neighbors lost lawn inflatables, including {V}'s nine-foot Santa and a snowman worth $340. A neighbor's camera showed a truck at {V}'s yard at 3 a.m., and two of the inflatables were found in {D}'s garage with {V}'s name on the tags.", "{D} found two deflated decorations at a curb, kept them in an open garage, and planned to sell them. The defense says the State cannot prove {DL} knew they were stolen or took them from any yard."),
        closings: ("A truck at the yard at 3 a.m., {V}'s name on the tags, and two inflatables in {D}'s garage four days later. {DL}'s curb story has no place, no date, and no witness.", "The camera shows a truck and no face, only two inflatables were found, and {D} showed them freely to a deputy. Finding something carelessly is not the same as stealing it."),
        timeline: [(0, "3 a.m.: the truck stops."), (0, "Morning: {V} finds the empty yard."), (4, "Deputies find the inflatables.")],
        identified: "A neighbor's camera.",
        impact: "My kids had waited all year to see him, and that nine-foot Santa has stood in our yard every December for eight years. When we woke up to an empty lawn, my youngest cried. We bought a smaller one, but it isn't the same. It took something out of the season for our family.",
        genders: ["D": .male])

    static let funeralScene = SmallCases.make(
        key: "story.funeralScene",
        category: .publicOrder,
        headlines: ["Man Screamed at Family During Funeral Service", "Disorderly Conduct Charge Outside Chapel"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance at a funeral, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "A man {D} walked into a funeral home chapel during a service on {DATE}, shouted at the family that the deceased 'owed him money,' and refused to leave until a deputy arrived. {DL}'s own brother had died the same year and {DL} says the funeral director had overcharged {D.him}. A funeral director was called as a witness.",
        state: [E(.video, 3, "Chapel Camera", "{D} shouts at the family during the eulogy."), E(.statement, 2, "Funeral Director", "{D} refused three requests to leave.")],
        defense: [E(.statement, 1, "Grief", "{DL}'s brother's funeral was two months earlier.")],
        role: "Funeral director",
        exam: [.direct("What is your role at the funeral home?", "\"I'm the funeral director. I arrange services, greet families, and make sure the chapel runs smoothly on the day.\""), .direct("What happened on {DATE}?", "\"During a 2 p.m. service, {D} walked into the chapel and began shouting at the family that the deceased owed {D.him} money.\""), .direct("How did the family react?", "\"They were stunned and several were crying. A grieving family had come to say goodbye, and the shouting interrupted the eulogy.\""), .direct("What did you do?", "\"I asked {DL} three times to leave, politely and then firmly. {DL} refused each time and kept shouting.\""), .direct("How long did it continue?", "\"From about 2 p.m. until a deputy arrived at 2:15. It felt much longer, because the family was trapped in the front rows.\""), .direct("What did the chapel camera capture?", "\"It shows {DL} walking down the aisle, shouting, and standing near the front, with mourners turning and staring.\""), .cross("Isn't it true {D}'s own sibling had died two months earlier?", "\"I knew that afterward. {D.his} sibling's funeral was held at our home, and I handled that arrangement too.\""), .cross("Did you invite the defendant to speak at that earlier service?", "\"I invited {DL} to say a few words, and then I cut {DL} off mid-sentence because the program was running long.\""), .cross("Did the defendant complain about the bill?", "\"{D.He} had questioned the charges afterward. I explained them, and I didn't think the matter was unresolved.\""), .cross("Did the defendant threaten anyone physically?", "\"No. {DL} shouted and refused to leave but didn't threaten or touch anyone.\""), .cross("Did you smell alcohol on the defendant?", "\"I did notice a smell of alcohol. I can't say how much {DL} had to drink.\"")],
        theory: ("{D} disrupted a funeral by shouting at the family.", "A grieving man's outburst."),
        allocution: "\"I'm ashamed, and I lost control. My sibling had died two months earlier, and the funeral bill was more than I could stand, and I walked into that chapel angry and grieving. What I said was wrong. I'm sorry to the family who was burying someone they loved.\"",
        truths: ("{DL} had been drinking at a bar down the road.", "The funeral director had invited {DL} to say a few words and cut {D.him} off mid-sentence."),
        defendant: [.direct("Why did you go into that chapel?", "\"My sibling had died two months earlier and the funeral bill had been more than I expected. I was angry and grieving.\""), .direct("What did you say?", "\"I said the deceased owed me money, which was wrong. I was mixing up my feelings about the bill and my loss.\""), .direct("Had you been drinking?", "\"I'd had some drinks at a bar down the road before I went. I won't deny it, and I regret that.\""), .direct("What happened at your own sibling's service?", "\"The director invited me to speak and then cut me off in the middle of a sentence. I never got to finish what I wanted to say.\""), .direct("Why didn't you leave when asked?", "\"I wasn't thinking clearly. I felt dismissed, as I had at my sibling's service, and I dug in.\""), .direct("What would you say to the family?", "\"I'm deeply sorry. They lost someone they loved, and I ruined part of that day with my own pain.\""), .cross("You walked into a funeral you weren't invited to?", "\"I didn't know the family. I just walked in. I had no business being there.\""), .cross("You were told three times to leave?", "\"Yes, and I refused each time. I know that was wrong.\""), .cross("You shouted over the eulogy?", "\"I did. I raised my voice over the person speaking, and I can see how much that hurt.\""), .cross("You had been drinking before going in?", "\"Yes, a few drinks. I was upset and thought it would help, and it made me worse.\""), .cross("Your sibling's bill was a private matter with the funeral home?", "\"It was. I should have called the home or gone to the office instead of the chapel during a stranger's service.\"")],
        openings: ("During a 2 p.m. funeral on {DATE}, {D} walked into the chapel, shouted at the grieving family that the deceased owed {D.him} money, and refused three requests to leave. The chapel camera caught it, and a deputy was needed to end it.", "{D}'s sibling had died two months earlier and {D.he} was grieving, angry about a bill, and cut off mid-sentence at that earlier service. The defense says this was a grieving person's outburst, not a crime."),
        closings: ("A family said goodbye while a stranger shouted over the eulogy and refused three requests to leave. The camera shows it, the director confirms it, and a funeral is no place to settle a bill.", "{D} was two months into grief, had been cut off at a sibling's service, and had been drinking down the road. A short, regretted outburst by someone in pain is not a deliberate disruption."),
        timeline: [(-60, "{DL}'s brother dies."), (0, "2 p.m.: the shout."), (0, "2:15 p.m.: a deputy arrives.")],
        identified: "The funeral director's call.",
        mood: .sympathetic,
        genders: ["D": .male])

    static let diveBarShooting = SmallCases.make(
        key: "story.diveBarShooting",
        category: .violent,
        headlines: ["Man Shot Outside Dive Bar After Closing-Time Argument", "Bartender Saw Two Men Leave Together Before Shots"],
        law: "murder2",
        threshold: 8,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 21...48,
        victim: true,
        summary: "{V} was shot once in the chest in the parking lot of a bar at 1:50 a.m. on {DATE} and died at the scene. The bartender saw {V} and {D} argue over a pool game and leave together at closing. A deputy found a .38 revolver in a storm drain 60 feet away. {DL} says {D.he} left first and drove home.",
        state: [E(.statement, 3, "Bartender", "{D} and {V} argued, then left together at closing."), E(.physical, 3, "Revolver", "A .38 revolver in a storm drain; {D}'s print on the cylinder.", .search), E(.forensic, 2, "Autopsy", "One gunshot wound to the chest from about six feet.")],
        defense: [E(.statement, 1, "Drove Home", "{DL} says {D.he} left first and was home by 1:45."), E(.statement, 2, "Neighbor", "A neighbor says {D}'s truck was in the driveway at about 2.")],
        role: "Sheriff's detective",
        exam: [.direct("How did this case come to you?", "\"A caller reported a body in the parking lot of a bar at 1:50 a.m. on {DATE}. {V} was lying near a truck with one gunshot wound to the chest.\""), .direct("What did the bartender tell you?", "\"That {V} and {D} argued over a pool game around 11:30 p.m. and that the two left together at closing, still talking.\""), .direct("What did the medical examiner find?", "\"One gunshot wound to the chest, fired from about six feet. {V} died at the scene, within a minute or two according to the autopsy.\""), .direct("What did you recover?", "\"Three days later a deputy found a .38 revolver in a storm drain sixty feet from where {V} fell. It had two spent casings in the cylinder.\""), .direct("What forensic evidence tied the revolver to {D}?", "\"A latent print on the cylinder, which the lab matched to {DL}. That was the first physical link we had between {DL} and the weapon.\""), .direct("What did the defendant say when interviewed?", "\"{D.He} said {D.he} left the bar first and drove home, arriving about 1:45. {D.He} said {D.he} never saw {V} in the lot.\""), .cross("Isn't it true no one saw the shooting?", "\"Correct. The bartender saw them leave together, but nobody has told me they watched the shot being fired.\""), .cross("Could a print on the cylinder be from handling the gun earlier?", "\"A print can come from handling at any time. I can't say when it was left, only that it was {D.his} and that the cylinder is hard to wipe.\""), .cross("Was the defendant's truck seen at the bar lot at 1:50?", "\"No. No camera covers the lot, and no one told me they saw {DL}'s truck there when the shots were fired.\""), .cross("Did you test the defendant's hands or clothes for gunshot residue?", "\"{D.He} was not arrested until nine days later, so residue testing would have been meaningless by then. We didn't do it.\""), .cross("Did you check what time the defendant actually got home?", "\"A neighbor says the truck was in the driveway around 2. The neighbor's clock may not have been accurate, and I didn't verify it.\"")],
        defenseRole: "Defendant's neighbor",
        defenseExam: [.direct("How do you know {D}?", "\"I live next door. We share a driveway fence, and I see {D}'s truck every day when I leave for work or come home.\""), .direct("Do you remember that night?", "\"I remember the night because of the sirens the next morning. I'd been up late with a sick child and was in the kitchen.\""), .direct("What did you see around 2 a.m.?", "\"{D.his} truck was in the driveway with the engine off. I looked out the window and noticed it as I passed by the sink.\""), .direct("How did you know the time?", "\"By the clock on my kitchen wall. It showed about two when I looked out at the truck.\""), .direct("Was the truck there earlier?", "\"Not when I first checked around midnight. I only saw it back by the time I looked out the second time.\""), .direct("How would you describe the defendant?", "\"A quiet neighbor. We've never had trouble, and I haven't seen {DF} angry or carrying a gun.\""), .cross("Is your kitchen clock set exactly right?", "\"It runs a bit off. I know it's not reliable to the minute, and it could be ten or twenty minutes fast or slow.\""), .cross("Did you see the defendant get out of the truck?", "\"No. I saw the truck only. I didn't see anyone get out or go into the house.\""), .cross("Did you hear the truck pull in?", "\"I didn't hear it arrive. I just noticed it parked in the driveway when I looked out.\""), .cross("You can't say when the truck got there, can you?", "\"No. It was there when I saw it around 2 by my clock, and I can't say how much earlier it was.\""), .cross("You're friendly with the defendant, aren't you?", "\"We're neighbors and we get along. I'm still telling you only what I saw.\"")],
        theory: ("{D} followed {V} into the lot and shot {V.him}.", "A print from handling and a neighbor who saw the truck home."),
        allocution: "\"I'll carry this for the rest of my life. We played pool and argued over a game, and it was only a bar argument. I paid my tab, drove straight home, and was in my driveway by a quarter to two. I'm sorry for the loss to {V.his} family, and I pray the real person is found.\"",
        truths: ("{DL} had pawned the revolver's twin the week before.", "The neighbor's clock was twenty minutes off."),
        defendant: [.direct("What happened between you and {V} at the bar?", "\"We played pool and got into an argument over a game. It was heated, but it was the kind of thing that happens at a bar, and I walked away.\""), .direct("When did you leave?", "\"Before closing. I paid my tab, went out to my truck, and drove straight home. I was in my driveway by about 1:45.\""), .direct("Did you see {V} in the parking lot?", "\"No. I never saw {V} outside. I left by the side door, because my truck was parked on the side near the road.\""), .direct("Do you own a revolver?", "\"I've handled revolvers over the years. I don't own a .38 now, and I can't tell you how a print of mine would end up on that one.\""), .direct("Did you hear any shots?", "\"No. I was already on the highway with the radio on. I didn't hear anything and didn't know about the shooting until the next day.\""), .direct("How did you feel when you heard that {V} was dead?", "\"Sick. We'd argued over a stupid game, and the next thing I know {V} is dead. I wanted to help the deputies figure it out.\""), .cross("You argued with {V} that night, didn't you?", "\"Yes, it was a loud disagreement over a shot on the table. I won't say it was nothing, but it was a pool game.\""), .cross("You left the bar at closing, around the same time as {V}?", "\"I left a little earlier than closing, I believe. I can't give the minute, and I know the bartender saw us leave around the same time.\""), .cross("Your print was on the revolver, wasn't it?", "\"That's what I'm told. I can't explain it. I know how it sounds, and I'm not going to make up a story.\""), .cross("You can't prove what time you got home, can you?", "\"My neighbor saw the truck about 2, and that's not exact. I don't have a camera at home, so I can't give you a clock.\""), .cross("A revolver like that was pawned by you a week before, wasn't it?", "\"I did pawn a gun about then because I needed cash. I'm not going to claim it's the one in the drain, but I know the question is fair.\"")],
        openings: ("{V} was shot once in the chest at 1:50 a.m. outside a bar after arguing with {D} over a pool game. The two left together at closing, and a revolver found in a storm drain sixty feet away carried {D.his} print on the cylinder.", "{D} left first, drove home, and was in the driveway when a neighbor looked out around 2. The defense says nobody saw the shot fired, and a print on a gun does not tell the jury when or how it got there."),
        closings: ("A pool game dispute, a departure together, a single shot from six feet, and a revolver in a drain bearing {D}'s print. Each fact points to the same person and the same night.", "The neighbor puts {D}'s truck in the driveway at about two, nobody saw the shooting, and the State cannot say when that print was made. Without more than an argument and a print, reasonable doubt remains."),
        timeline: [(-1, "11:30 p.m.: the pool game dispute."), (0, "1:45 a.m.: {DL} says {D.he} was home."), (0, "1:50 a.m.: shots in the parking lot."), (3, "The revolver is found in a storm drain."), (9, "{DL} is arrested.")],
        identified: "A bartender and a revolver in a drain.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        impact: "My brother went out for one beer and never came home. {V.He} played pool every Friday with the same crowd, and {V.he} never had trouble with anyone. We got the call before sunrise. I think about that parking lot every night, and I want to know who left {V.him} there.",
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .male, "V": .male])

    static let schoolZoneCrash = SmallCases.make(
        key: "story.schoolZoneCrash",
        category: .traffic,
        headlines: ["Speeding Driver Hits Crossing Guard Near Elementary School", "Crash in School Zone Leaves Guard in Hospital"],
        law: "seriousInjuryVehicle",
        threshold: 6,
        spec: "Operated a motor vehicle in a school zone while impaired, causing serious injury to {V}, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "A crossing guard, {V}, was struck at 7:50 a.m. on {DATE} while waving children across. A car did not stop. A bus driver followed it and a deputy stopped {D} three blocks away. Blood drawn two hours later showed a 0.09. {DL} says {D.he} had two drinks the night before and the sun was in {D.his} eyes.",
        state: [E(.forensic, 3, "Blood Test", "0.09 two hours after the crash."), E(.statement, 2, "Bus Driver", "{D}'s car did not stop and the bus driver followed it."), E(.video, 2, "School Camera", "A silver sedan at about 45 mph in the zone.")],
        defense: [E(.statement, 1, "Sun", "{DL} says the low sun blinded {D.him} and {D.he} was sober.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What was the speed limit where {V} was struck?", "\"The school zone limit is 20 miles an hour. It was 7:50 in the morning, when children were crossing, and {V} was in the road as the crossing guard.\""), .direct("How fast was the car going?", "\"My reconstruction put it at about 45 miles an hour at impact. The car did not stop, and a bus driver followed it until a deputy stopped {D}.\""), .direct("What was the blood alcohol result?", "\"The blood draw showed 0.09. It was taken about two hours after the crash, once {D.he} had been stopped and processed.\""), .direct("What did you find when you arrived at the crossing?", "\"The crossing guard was on the pavement near the curb with a leg injury, and children were gathered on the sidewalk. A deputy had stopped a silver sedan three blocks away.\""), .direct("How did you establish the speed of the car?", "\"From the school's camera video, frame by frame, and from a skid and yaw analysis. Both put the car at about 45 miles an hour in a zone posted for 20.\""), .direct("What happened when you spoke with {D}?", "\"{DL} said {D.he} didn't realize {D.he} had hit anyone and that the sun was bright. I smelled alcohol on {D.his} breath and arranged for a blood draw.\""), .cross("The test was two hours after the crash, wasn't it?", "\"Yes, two hours. The level at the time of driving would be different, and an expert can speak to that better than I can.\""), .cross("The sun was low that morning, wasn't it?", "\"It was low in the east. I noted glare as a possible factor, though glare does not explain driving 45 in a 20 zone.\""), .cross("Did you see the defendant drink anything after the crash?", "\"No. Nothing suggests {DL} drank after the crash. I have no evidence of that.\""), .cross("Did anyone see the defendant drink that morning?", "\"No. The only evidence of drinking is the odor I noticed and the blood result. I did not find an open container in the car beyond what was reported.\""), .cross("Did the bus driver keep the defendant's car in sight the whole time?", "\"The bus driver followed it for several blocks but admitted losing sight of it briefly. I can't tell you how long, but it was less than a minute.\"")],
        defenseRole: "Toxicologist",
        defenseExam: [.direct("Could the level at the crash have been different from the level at the draw?", "\"Yes. Alcohol levels change over time, and two hours is a long gap. It depends on whether absorption had finished.\""), .direct("Which direction would it go?", "\"Usually the level would be higher at the earlier time, if absorption was finished. If it was still rising, the opposite could be true.\""), .direct("What would you need to know to be more precise?", "\"I would need when {D} last drank, how much, and what {D.he} ate. Without that, any back-calculation is an estimate.\""), .direct("What is your field, and what were you asked to review?", "\"I'm a forensic toxicologist. I reviewed the blood result and the timeline, and I looked at how alcohol is absorbed and eliminated.\""), .direct("How is the 0.09 two hours after the crash relevant to the time of driving?", "\"It's a snapshot after a delay. Depending on when {D.he} last drank, the level at the time of the crash could have been higher or lower, and I need more information to say.\""), .direct("What would change your calculation?", "\"If {D.he} was still absorbing a late drink, the level could have been rising, so it might have been lower at the crash. If {D.he} last drank at midnight, the level would have been falling.\""), .cross("Is there any evidence {D} drank after the crash?", "\"Nothing I have seen suggests it. I'm not assuming that happened.\""), .cross("A level of 0.09 is above the legal limit of 0.08, isn't it?", "\"Yes. It is above the limit, though only slightly. Whether {D.he} was above it while driving is the question.\""), .cross("Can you say what the defendant's level was at 7:50?", "\"No. I can offer a range, but I cannot give you an exact number.\""), .cross("If the defendant only had two drinks the night before, would a 0.09 be expected at 10 a.m.?", "\"No. Two drinks the night before would normally leave no measurable alcohol by morning, so I would need to understand why the level was that high.\""), .cross("Is it possible the defendant drank more than reported?", "\"It is possible. I can only analyze what I am told and what the test shows, and I can't rule out additional drinking.\"")],
        theory: ("{D} drove drunk and fast through a school zone.", "The sun, and a test taken late."),
        allocution: "\"I hope you walk again. I had two drinks the night before, and I wasn't drinking that morning, and the sun was right in my eyes as I came over the rise. I didn't see you until I was close. I think about those children and the way you stood to guide them.\"",
        truths: ("A bottle was found in {DL}'s glove box, half empty.", "The bus driver admitted losing sight of the car for a block."),
        defendant: [.direct("Had you been drinking before you drove?", "\"I had two drinks the night before. I was not drinking that morning, and I did not feel impaired when I drove.\""), .direct("Did you see {V} in the crosswalk?", "\"Not until very late. The sun was right in my eyes as I came over the rise, and I did not see {V.him} until I was close.\""), .direct("Why didn't you stop?", "\"I did not realize what had happened at first. I thought I may have hit something small, and I did not understand that someone was hurt.\""), .direct("Tell the jury what you did the night before the crash.", "\"I had a couple of drinks at a gathering with friends, finished around midnight, and went home to sleep. I felt fine in the morning and drove to work.\""), .direct("What were the conditions on the road that morning?", "\"Clear and cold, with the sun just above the trees to the east. It was straight in my eyes through the windshield.\""), .direct("What happened when you saw the trooper's lights?", "\"I pulled over right away. I told the trooper about the sun and the drinks the night before and agreed to the blood test.\""), .cross("The speed limit was 20 and you were going about 45. Can you explain that?", "\"I do not think I was going that fast. I was probably going faster than I should have, but I was not watching the speedometer.\""), .cross("A bottle was found in your glove box, wasn't it?", "\"Yes, from a party a while back. It had been there a while, and I had not touched it that morning.\""), .cross("You left the scene of a crash with a crossing guard on the ground, didn't you?", "\"I did not know the extent of it. I was shocked, and I should have stopped. I will carry that.\""), .cross("You didn't stop for the crossing guard. Why not?", "\"I didn't see {V}. The glare was blinding, and I didn't know I'd struck anyone until the deputy told me.\""), .cross("Did you slow down when you saw the school sign?", "\"I don't remember seeing it. If I had, I would have slowed, and that's why I'm sorry.\"")],
        openings: ("At 7:50 in the morning, a crossing guard was struck in a school zone by a car doing about 45 in a 20. A deputy stopped {D} three blocks away, and blood drawn later showed a 0.09.", "The defense will present a low morning sun, a blood test taken two hours late, and a driver who did not realize what happened. Glare and a delayed test are real doubt."),
        closings: ("Forty-five in a twenty zone, a crossing guard on the ground, a car that did not stop, and a 0.09 two hours later. Whatever the sun was doing, {D} drove impaired through a school zone.", "A test taken two hours late and a sun that blinded drivers heading east are not facts the State can dismiss. Before you convict, ask what the level really was when {D} was driving."),
        timeline: [(-1, "Night: {DL} drinks at a party."), (0, "7:50 a.m.: {V} is struck at the crossing."), (0, "7:58 a.m.: a deputy stops {DL}'s car."), (0, "10 a.m.: blood is drawn.")],
        identified: "A bus driver who followed the car.",
        aggravating: [],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .wantsConviction,
        impact: "I walked those children across that street for nine years, and I knew every one of their names. Now I can't stand on my leg for more than a few minutes. I spent weeks in the hospital, and I'm still learning to walk again. I miss my kids at the crosswalk.",
        doctrines: ["burdenOfProof"])

    static let homeInvasionBurglary = SmallCases.make(
        key: "story.homeInvasionBurglary",
        category: .property,
        headlines: ["Family Held in Bedroom During Night Break-In", "Intruder Ransacks House While Residents Hide"],
        law: "burglary1",
        threshold: 7,
        spec: "Broke and entered the occupied dwelling of {V} at night with intent to commit larceny therein, on {DATE}.",
        ages: 20...45,
        victim: true,
        summary: "At 2 a.m. on {DATE}, {V} heard glass break and locked the family in a bedroom while the intruder emptied drawers and took a safe. A palm print was found on the kitchen window. {D} was stopped the next day driving a truck matching a neighbor's description. {DL} says {D.he} was at a girlfriend's all night.",
        state: [E(.forensic, 3, "Palm Print", "A palm print on the broken kitchen window matches {D}."), E(.statement, 2, "Neighbor", "A truck matching {D}'s was parked on the block at 1:30 a.m."), E(.document, 1, "Phone Tower", "{D}'s phone was near the house at 2 a.m.")],
        defense: [E(.statement, 2, "Girlfriend", "{DL}'s girlfriend says {D.he} was with her all night.")],
        role: "Sheriff's detective",
        exam: [.direct("What was the report on {DATE}?", "\"A family reported a home invasion at 2 a.m. Glass broke in the kitchen, and the intruder emptied drawers and took a safe while the family hid.\""), .direct("How did {V} respond?", "\"{V} heard the glass break, woke the family, and locked everyone in an upstairs bedroom. {V} called 911 and stayed on the line.\""), .direct("What did you find at the house?", "\"A broken kitchen window, drawers pulled out and emptied, and a heavy safe gone from the den. It had been carried out through the back.\""), .direct("What physical evidence was recovered?", "\"A palm print on the broken kitchen window. The lab matched it to {D}.\""), .direct("What did neighbors report?", "\"One neighbor saw a truck parked on the block at about 1:30 a.m. It matched the description of {D.his} truck, and {D.he} was stopped in one the next day.\""), .direct("What did {D}'s phone show?", "\"{D.his} phone was on a tower near the house at 2 a.m. That doesn't pinpoint a location, but it fit the other evidence.\""), .cross("Isn't it true no one saw the intruder's face?", "\"Correct. The family stayed locked in the bedroom, and the neighbor saw only a truck, not who was driving.\""), .cross("Did anyone see the truck at the house itself?", "\"The neighbor saw it parked on the block at 1:30. Nobody saw it at the house at the time of the break-in.\""), .cross("How precise is a tower location for a phone?", "\"Not very. A tower covers a wide area, several blocks in every direction. I can't tell you the phone was at the house.\""), .cross("Was the safe ever recovered?", "\"Later, yes, in a creek behind a relative's house. {D.his} name wasn't on anything there, and I can't say who put it in the water.\""), .cross("Did the defendant say where {D.he} was?", "\"{D.He} said {D.he} was at a girlfriend's all night. I interviewed the girlfriend, and the girlfriend said the same.\"")],
        defenseRole: "Defendant's girlfriend",
        defenseExam: [.direct("How do you know {D}?", "\"{D} is my partner of about a year. We spend most nights together, and we were together on the night in question.\""), .direct("What time did the defendant arrive that night?", "\"Around 11 p.m. I remember because I'd just finished a show, and {D.he} came in the door with a bag of food.\""), .direct("What did you do together?", "\"We ate, watched TV, and went to bed around midnight. We were in the apartment the entire night.\""), .direct("Did the defendant leave at any point?", "\"No. I woke up once around two, and {D.he} was asleep next to me. I'm a light sleeper and I'd have noticed.\""), .direct("Do you have a doorbell camera?", "\"Yes. It shows {DF} arriving at 11 p.m., and it doesn't show {DF} leaving. I gave that to the detective.\""), .direct("What did you tell the detective?", "\"The same thing I'm telling you. I said {D.he} was with me all night, and I've never wavered on that.\""), .cross("You were asleep for part of the night, weren't you?", "\"I slept from about midnight on, with a couple of wake-ups. I can't account for every minute while I slept.\""), .cross("Does your doorbell camera cover every door?", "\"It covers the front door. There's a back door the camera doesn't see, and I know how that sounds.\""), .cross("You care about the defendant, don't you?", "\"I do. But I wouldn't lie under oath, and I told the detective the truth when I first spoke to {D.him}.\""), .cross("How far is your apartment from the family's house?", "\"Not far, maybe a ten-minute drive. I haven't measured it.\""), .cross("Did you hear the defendant's truck start up in the night?", "\"No. I'd have been asleep, and I didn't hear anything, but I'm not sure I would.\"")],
        theory: ("{D} broke in while a family hid upstairs.", "A print and a girlfriend's alibi."),
        allocution: "\"I know what that night did to your family, and I regret it. I wasn't there. I was at my girlfriend's from eleven until morning, and I've never been to your house. I don't know how my print could be on that window, and I'm asking the court to look closely at everything.\"",
        truths: ("The safe was found in a creek behind {DL}'s cousin's house.", "The girlfriend's doorbell camera showed {DL} arrive at 11 p.m. and never leave."),
        defendant: [.direct("Where were you the night of the break-in?", "\"At my girlfriend's. I got there around 11 p.m. and stayed through the morning. I never left that night.\""), .direct("Have you ever been to the family's house?", "\"No. I've never been to that house and I don't know the people. I don't know how my print could be on that window.\""), .direct("What kind of truck do you drive?", "\"A common work truck, the same model hundreds of people have around here. I was driving it the next day when I was stopped.\""), .direct("What about your phone and the tower?", "\"My girlfriend's place is on the same side of town. I'm told the tower covers both, so it doesn't show where I actually was.\""), .direct("How did you feel when deputies stopped you?", "\"Confused. They asked about a break-in and I told them I'd been at my girlfriend's and gave the girlfriend's name and number.\""), .direct("Do you have any connection to a safe being found in a creek?", "\"None. I heard about it afterward. I don't own a safe, and I never went near any creek.\""), .cross("A palm print on the window is yours, isn't it?", "\"That's what the lab said. I can't explain it, and I understand it's a hard fact for me.\""), .cross("Your girlfriend is the only person who puts you at the apartment?", "\"The girlfriend and the camera at the front door, I think. I'm not sure what the doorbell recorded, but I know I was there.\""), .cross("You arrived at 11 p.m.?", "\"About then, yes. I wasn't looking at a clock, but I know it was before midnight.\""), .cross("You didn't call anyone that night to show where you were?", "\"No, I was with my girlfriend and didn't think I'd need to prove it. I wish I'd taken a photo.\""), .cross("A truck like yours was parked on that block at 1:30 a.m.?", "\"So I'm told. There are plenty like it, and mine was parked at my girlfriend's.\"")],
        openings: ("At 2 a.m. a family locked themselves in an upstairs bedroom while an intruder broke a kitchen window, emptied drawers, and carried out a safe. A palm print on that window matches {D}, and a truck like {D.his} was parked on the block at 1:30.", "{D} was at a girlfriend's apartment all night, and the girlfriend's doorbell camera shows {DL} arriving at 11 and never leaving. The defense says a print and a common truck do not outweigh that record."),
        closings: ("A palm print on the broken window, a truck matching {D}'s on the block, and a phone near the house at 2 a.m. They fit together on a night when a family hid in terror.", "The camera shows {D} arriving at 11 and the girlfriend says {D.he} stayed all night. A print can't tell you when it was made, and the neighbor saw a truck, not a face."),
        timeline: [(0, "1:30 a.m.: a truck is parked on the block."), (0, "2 a.m.: the window breaks and the family hides."), (0, "2:20 a.m.: the safe is carried out."), (1, "{DL} is stopped in a matching truck.")],
        identified: "A palm print on the window.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "My children still sleep in our bed. We heard glass break at two in the morning, and I locked us in the bedroom while a stranger went through every drawer in our house. I couldn't say a word to them for an hour. They won't sleep alone, and I don't blame them.",
        doctrines: ["burdenOfProof"])

    static let carjackingRobbery = SmallCases.make(
        key: "story.carjackingRobbery",
        category: .robbery,
        headlines: ["Driver Forced Out of Car at Gas Station at Gunpoint", "Carjacking Suspect Found With Victim's Phone"],
        law: "dangerousRobbery",
        threshold: 8,
        spec: "Took a 2017 sedan and a wallet from the person and presence of {V} by endangering and threatening {V.his} life with a firearm, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "At 9:10 p.m. on {DATE}, {V} was pumping gas when a man put a gun against {V.his} side and took the car keys and wallet. The car was found abandoned two days later. {D} was stopped using {V}'s phone. {DL} says {D.he} bought the phone from a stranger.",
        state: [E(.statement, 3, "Victim", "{V} identifies {D} from a photo array at 90% certainty."), E(.digital, 3, "Phone", "{V}'s phone was in {D}'s pocket and used by {D} for two calls."), E(.video, 2, "Gas Station Camera", "A man in a gray hooded sweatshirt approaches {V}.")],
        defense: [E(.statement, 1, "Stranger", "{DL} says {D.he} bought the phone for $40.")],
        role: "Police officer",
        exam: [.direct("What was the first report?", "\"On {DATE} around 9:10 p.m., {V} reported being robbed at gunpoint at a gas pump. The robber took the car keys and a wallet and drove off.\""), .direct("How did {V} describe it?", "\"{V} said a person in a gray hooded sweatshirt walked up, pressed a gun against {V}'s side, and said to hand over the keys and wallet.\""), .direct("What did the gas station camera show?", "\"A person in a gray hooded sweatshirt approaches {V} at the pump, speaks briefly, and then leaves in the car. The face is partly covered.\""), .direct("What happened to the car?", "\"It was found abandoned two days later. There was no sign of the robber, and the car was returned to {V} after processing.\""), .direct("How did {D} become a suspect?", "\"{V}'s phone was tracked, and calls went to a new number. Three days after the carjacking, {D} was stopped with {V}'s phone in a pocket.\""), .direct("Did {V} identify the defendant?", "\"{V} picked {DL} from a photo array and said 90 percent sure. {V} said the build and the voice matched.\""), .cross("Isn't it true {V} said only 90 percent?", "\"Yes. {V} was fairly confident but didn't say 100 percent, and I recorded exactly what {V} said.\""), .cross("Did {V} see the robber's whole face?", "\"Only part of it. The hood and the dark limited the view, so {V} was relying on the eyes, the build, and the voice.\""), .cross("Did you find a gun on the defendant?", "\"No. {D.He} had no weapon when stopped, and no gun was recovered in the car or from {D.his} home.\""), .cross("Does the phone tell you who took the car?", "\"Not on its own. It tells me {DL} had the phone three days later. {DL} says {D.he} bought it for $40.\""), .cross("Were the defendant's fingerprints in the stolen car?", "\"No. The car was processed and there were no prints we could match to {D.him}.\"")],
        defenseRole: "Defendant's cousin",
        defenseExam: [.direct("How are you related to {D}?", "\"I'm {D}'s cousin. We grew up near each other and see each other almost every week.\""), .direct("Did the defendant show you a phone around that time?", "\"Yes, a few days after. {D.He} said {D.he} bought it from a guy for $40 and was happy with the deal.\""), .direct("Did the defendant seem to be hiding it?", "\"No. {D.He} used it in front of me and called family on it. {D.He} wasn't secretive at all.\""), .direct("Do you know the defendant to own a gun?", "\"No. I've never seen {DF} with a gun and I'd be surprised. {DF} isn't that kind of person.\""), .direct("How would you describe the defendant's character?", "\"Easygoing. {DF} has had trouble with money, but I've never seen {DF} threaten anyone.\""), .direct("Where was the defendant the evening of the carjacking?", "\"I can't say for certain. I know {D.he} was around and on the phone with family that week, but I don't have an exact time.\""), .cross("You weren't with the defendant when the phone was bought, were you?", "\"No. I wasn't there, so I only know what {D.he} told me about the purchase.\""), .cross("You can't say where the defendant was at 9:10 that night?", "\"No, I can't. I was home that night and didn't see {D.him}.\""), .cross("Did you ask the defendant where the phone came from?", "\"I asked, and {D.he} gave me the same answer, a stranger and $40. I didn't ask for more.\""), .cross("Did you wonder about the low price?", "\"A little. I thought it was a good deal, and I didn't think about stolen goods.\""), .cross("You'd want the best for the defendant, wouldn't you?", "\"I would, and that's why I'd want {DF} to tell the truth. I think {DF} is.\"")],
        theory: ("{D} took a car at gunpoint.", "A phone bought from a stranger and a hood."),
        allocution: "\"I bought that phone for forty dollars from a stranger near the bus station, and I had no idea it belonged to someone who'd been robbed. It looked like any used phone. I know that doesn't excuse me, and I'll return it today.\"",
        truths: ("The phone's calls went to {DL}'s mother.", "The phone had been resold twice before {DL} bought it, a pawn record shows."),
        defendant: [.direct("Where did you get the phone?", "\"I bought it from a stranger for $40. I was walking near the bus station, and someone offered it cheap.\""), .direct("Did you know whose phone it was?", "\"No. I had no idea it belonged to a victim of a robbery. It looked like a normal used phone with no case.\""), .direct("Whom did you call with it?", "\"I made a couple of calls to family. I wasn't hiding, and I used the phone openly.\""), .direct("Were you at the gas station that night?", "\"No. I've never been to that gas station, and I didn't take anyone's car.\""), .direct("Do you own a gray hooded sweatshirt?", "\"I own a couple of hoodies. So does everyone I know, and that's not much of a description.\""), .direct("What did you do when deputies stopped you?", "\"I told them I'd bought the phone and handed it over. I wasn't nervous, because I didn't know it was stolen.\""), .cross("You can't name the person who sold you the phone?", "\"No. It was a quick sale and I never got a name. I know that makes it hard to check.\""), .cross("$40 for a recent phone didn't make you suspicious?", "\"It did, a little. I didn't think it meant someone was carjacked. I thought it might be used or damaged.\""), .cross("You called your parent with it?", "\"I did. I was calling family, and I didn't think about hiding anything.\""), .cross("The victim picked you from a photo array?", "\"I'm told so. I'd say the victim was mistaken, because I wasn't there.\""), .cross("You were stopped three days later with the phone in your pocket?", "\"Yes. I had it with me because I was using it, and I didn't know anyone had been robbed.\"")],
        openings: ("At 9:10 p.m. a person in a gray hooded sweatshirt pressed a gun to {V}'s side at a gas pump and drove away with the car, keys, and wallet. Three days later {D} was stopped with {V}'s phone in a pocket, and {V} picked {DL} from a photo array.", "{D} bought a cheap phone from a stranger near the bus station and used it openly to call family. The defense says possession of a phone is not a carjacking, and a 90 percent identification from a hooded face is not enough."),
        closings: ("{V}'s phone was in {D}'s pocket three days after the carjacking and was used for two calls. Add a 90 percent identification and a gray hooded sweatshirt on camera, and the pieces fit.", "A hood, a dark lot, a 90 percent identification, and a $40 phone from a stranger. There is no gun, no print, and no trace of {D} in the car, so the State has not proved who was holding the weapon."),
        timeline: [(0, "9:10 p.m.: the carjacking."), (1, "{V}'s phone shows calls to a new number."), (2, "The car is found abandoned."), (3, "{DL} is stopped with the phone.")],
        identified: "The victim's phone in {DL}'s pocket.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        impact: "I can't pump gas without shaking. A man pushed a gun against my side while the pump was running, and I handed over my keys and wallet. My hands still tremble at the station. I take the bus now when I can, and I stay in the car with the doors locked when I can't.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let apartmentFire = SmallCases.make(
        key: "story.apartmentFire",
        category: .property,
        headlines: ["Fire at Apartment Building Forces Evacuation of 18 Residents", "Fire Marshal Finds Accelerant Trail in Hallway"],
        law: "arson1",
        threshold: 7,
        spec: "Willfully and maliciously burned an occupied dwelling of {V}, a landlord, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "A fire started in the first-floor hallway of a 12-unit building at 3 a.m. on {DATE}. Eighteen residents escaped; one firefighter was treated for smoke. The fire marshal found a gasoline trail. {D}, evicted from unit 1B a week earlier, was seen on a corner camera near the building at 2:40. {DL} says {D.he} was walking {D.his} dog.",
        state: [E(.forensic, 3, "Fire Marshal", "A gasoline trail from the lobby door to unit 1B."), E(.video, 2, "Corner Camera", "{D} on the corner at 2:40 a.m. holding a red can."), E(.document, 2, "Eviction Notice", "{D} evicted from 1B a week earlier.")],
        defense: [E(.statement, 1, "Dog", "{DL} says {D.he} was walking {D.his} dog and carrying a water jug.")],
        role: "Fire marshal",
        exam: [.direct("What did you find when you arrived?", "\"A 12-unit apartment building with fire in the first-floor hallway. Eighteen residents had escaped, and one firefighter was treated for smoke.\""), .direct("How did you determine the cause?", "\"I found a gasoline trail running from the lobby door to unit 1B. The burn pattern followed it, and it's a clear sign of an accelerant.\""), .direct("How did {D} come into the case?", "\"{D} had been evicted from unit 1B a week before the fire. The eviction notice and the trail pointing to that unit made {DL} a suspect.\""), .direct("What did the corner camera show?", "\"{DL} on the corner near the building at 2:40 a.m., holding a red can. The fire began about twenty minutes later, at 3.\""), .direct("What was found in the defendant's possession?", "\"A $14 gasoline receipt from the previous night. It was in {D.his} wallet when {D.he} was brought in.\""), .direct("What damage was done?", "\"The hallway and unit 1B were heavily damaged, and several apartments suffered smoke and water damage. Eighteen people lost their homes for a time.\""), .cross("Isn't it true the camera does not show anyone lighting anything?", "\"Correct. It shows {DL} at the corner at 2:40. It does not show the building or any ignition.\""), .cross("Did you see a dog in the corner footage at 2:40?", "\"I looked and I didn't see one. {D.He} appears alone in the frame, holding what looks like a red can.\""), .cross("Could the red can be a water jug?", "\"It could be, from that camera. The image is grainy and I can't read a label from that distance.\""), .cross("Is a $14 receipt a lot of gasoline?", "\"About three to four gallons. It's consistent with a can, but also with a lawn mower or a car.\""), .cross("Was the defendant near the building at 3 a.m.?", "\"I have no record of that. The last I see of {DL} is the corner camera at 2:40.\"")],
        defenseRole: "Defendant's neighbor",
        defenseExam: [.direct("How do you know {D}?", "\"I'm a neighbor, and I live on the same block. I've known {D} for about three years and I see {DF} often.\""), .direct("What do you know about the defendant's dog?", "\"{D.He} has a dog and walks it every night, often late. I've seen them out at all hours.\""), .direct("What does the defendant carry on those walks?", "\"A jug of water for the dog. {D.He} refills it and carries it in a plastic container.\""), .direct("Have you seen the defendant with gasoline cans?", "\"No. I've never seen {DF} with a gas can. {DF} walks, mostly, and the car is old.\""), .direct("How did the defendant react to the eviction?", "\"Hurt and angry, but not violent. {D.He} told me about it and said {D.he} was looking for a new place.\""), .direct("What kind of person is the defendant?", "\"Kind. {DF} helped me carry groceries and watches my place when I'm away. I'd never think of {DF} as dangerous.\""), .cross("You didn't see the defendant on the night of the fire?", "\"No. I was asleep, and I didn't see {D.him} that night. I'm telling you what I've seen on other nights.\""), .cross("A red container could hold water or gas, couldn't it?", "\"It could. I've only seen the container as a water jug, but I can't say what was in it that night.\""), .cross("You can't say the dog was with the defendant that night, can you?", "\"No. I wasn't there, and I can't tell you whether the dog went out at 2:40.\""), .cross("You know the defendant was upset about the eviction?", "\"I do. {D.He} told me, and I saw it. That doesn't mean {D.he} burned anything.\""), .cross("You're a friend of the defendant's, aren't you?", "\"I am. I'm giving you honest answers about what I know, and I'm not hiding anything.\"")],
        theory: ("{D} burned the building where {D.he} was evicted.", "A dog walk and a water jug."),
        allocution: "\"I wish I had never been angry, and I'm sorry. I was evicted from 1B a week before, and I was upset, but I was trying to move on and find a new place. I was just walking my dog on the corner that night. I'm sorry for the families who lost everything.\"",
        truths: ("A gas receipt for $14 was in {DL}'s wallet from the night before.", "The dog was not in the corner footage at 2:40."),
        defendant: [.direct("Where were you at 2:40 that morning?", "\"On the corner, walking my dog. I walk my dog late at night most nights, and I carried a water jug for the dog.\""), .direct("Were you evicted from that building?", "\"Yes, from 1B a week earlier. I was angry about it, but I was trying to move on and find a new place.\""), .direct("What was in the red container?", "\"A water jug, a red plastic one I carry for the dog. I didn't carry gasoline.\""), .direct("What about the gas receipt?", "\"I bought a little gas the night before for my car, which was low. I keep it in my wallet because I forget to throw things out.\""), .direct("Did you set the fire?", "\"No. I would never burn a building with 18 people inside. Some of those people were my neighbors and friends.\""), .direct("What did you do when you heard about the fire?", "\"I felt sick. I went to the building the next day to see if my old neighbors were okay.\""), .cross("You were evicted a week earlier, weren't you?", "\"Yes, and I was upset. I thought the eviction was unfair, and I won't pretend I wasn't angry at the landlord.\""), .cross("The dog isn't in the corner footage, is it?", "\"I'm told it isn't. The dog was on a leash behind me, and the camera angle may not catch it.\""), .cross("You were a block from the building at 2:40, twenty minutes before the fire?", "\"Yes, I was near the building. I live close, and I walk that route all the time.\""), .cross("You bought gasoline the night before?", "\"I did, $14 worth. It was for my car. I didn't use it on any building.\""), .cross("The gasoline trail led to your old unit, didn't it?", "\"So the marshal says. I can't explain that, but I didn't do it.\"")],
        openings: ("At 3 a.m. a fire ripped through the first-floor hallway of a 12-unit building, and eighteen people escaped. The fire marshal found a gasoline trail leading to unit 1B, where {D} had lived until an eviction a week earlier, and a corner camera caught {DL} holding a red can at 2:40.", "{D} walks a dog late at night with a water jug, lives nearby, and was seen on a corner camera, not at the building. The defense says the State has an angry former tenant and a grainy image, but nothing that shows who lit that hallway."),
        closings: ("An eviction, a gasoline receipt, a red can at 2:40, and a gasoline trail running to {D}'s old unit. Eighteen people ran out into the night, and the motive and the opportunity belong to {DL}.", "The camera shows a person on a corner with a red container and no dog in view, and nothing shows a match struck. A water jug, a dog walk, and a receipt for a car are consistent with innocence, and the State bears the burden."),
        timeline: [(-7, "{DL} is evicted from 1B."), (-1, "{DL} buys gasoline."), (0, "2:40 a.m.: {DL} is on the corner."), (0, "3 a.m.: the fire begins.")],
        identified: "A corner camera and the fire marshal's trail.",
        aggravating: ["The offense endangered the lives of many people"],
        mood: .wantsConviction,
        impact: "We lost everything. My daughter's room is ash, and so are her drawings and her books. Eighteen of us ran out into the cold at three in the morning with nothing on our feet. We've been in a motel for weeks. I just want to give her a bedroom again.",
        doctrines: ["burdenOfProof"])

    static let parkingLotAbduction = SmallCases.make(
        key: "story.parkingLotAbduction",
        category: .violent,
        headlines: ["Woman Forced Into Van in Grocery Parking Lot, Escapes", "Witness Records Van Plate in Abduction Attempt"],
        law: "kidnapping2",
        threshold: 8,
        spec: "Unlawfully confined, restrained, and removed {V} from one place to another for the purpose of terrorizing {V.him}, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "At 6:30 p.m. on {DATE}, a man grabbed {V} in a grocery parking lot and pulled {V.him} into a white van. {V} jumped out at a stoplight half a mile away. A witness wrote down a plate. The van belongs to {D}. {DL} says {D.he} lent the van to a coworker that day.",
        state: [E(.statement, 3, "Victim", "{V} identifies {D} in a lineup."), E(.statement, 2, "Parking Lot Witness", "A witness wrote down the van's plate."), E(.document, 2, "Registration", "The van is registered to {D}.")],
        defense: [E(.statement, 1, "Loaned Van", "{DL} says a coworker borrowed the van that day.")],
        role: "Police detective",
        exam: [.direct("How did you identify {D}?", "\"A witness wrote down the van's plate, and the plate came back to {D}. {V} was then shown a lineup that included {DL}.\""), .direct("Whose van is it?", "\"The van is registered to {D.him}. It is white, and it matches the description {V} gave of the vehicle.\""), .direct("What did {V} tell you about the abduction?", "\"{V} said that at 6:30 p.m. someone grabbed {V.him} in a grocery parking lot and pulled {V.him} into the van, and that {V.he} jumped out at a stoplight half a mile away.\""), .direct("What did the witness who wrote down the plate tell you?", "\"The witness was loading groceries two cars away. A white van pulled in fast, someone hurried toward {V}, and the van left a moment later with {V} inside. The witness copied the plate from a few feet away.\""), .direct("How did {V} get away?", "\"{V} jumped out at a stoplight half a mile away and ran into a gas station. {V} was scraped and shaken but able to describe what happened.\""), .direct("What did you do to check the van that was registered to the defendant?", "\"We photographed and searched it. We looked for anything tying it to {V}, and I wrote up what we found and did not find in my report.\""), .cross("{D} says a coworker had the keys that day, doesn't {D.he}?", "\"Yes, that is what {D.he} told me. I spoke to the coworker, and the coworker denied borrowing the van.\""), .cross("{V} saw the person for only a few seconds, correct?", "\"Yes. It was a very short time, and it was a frightening event. That affects how clear any identification can be.\""), .cross("Did you consider whether the lineup was fair?", "\"I followed our procedure. I know {D.his} side says it was unfair, but I did not see any problem at the time.\""), .cross("How long did {V} see the person who grabbed {V.him}?", "\"A few seconds at most in the parking lot, and a minute or so inside the van. It was dusk, and the lighting in the lot was uneven.\""), .cross("Did you recover anything from the van that tied it to {V}?", "\"No. We processed the interior and did not find anything belonging to {V}, though the van had been cleaned recently.\"")],
        defenseRole: "Defendant's coworker",
        defenseExam: [.direct("Did you borrow {D}'s van on that day?", "\"No, I did not. I never had the van that day, and I have never taken it without asking.\""), .direct("Where were you at 6:30 that evening?", "\"I was at home. I can tell you what I was doing, but I did not have a witness there with me.\""), .direct("Do you know anything about this case?", "\"Only what deputies told me when they came to ask. I was surprised when they said {D}'s van was involved.\""), .direct("How do you know the defendant?", "\"We work at the same company, on the same shift, and we have lunch together a few times a week.\""), .direct("Did you ever borrow the defendant's van?", "\"Not that I recall. I have ridden in it once or twice, but I don't remember ever having the keys.\""), .direct("What did you do on the evening of the incident?", "\"I was at home. I watched a game and went to bed early, and I didn't see anyone that night.\""), .cross("So the defendant's account that you had the keys is not accurate, is it?", "\"I did not have the keys that day. I can only tell you that, and I do not know why {D.he} would say it.\""), .cross("Do you have a key to the van?", "\"Not that I recall. I may have used it long ago, but not recently.\""), .cross("Do you know where the defendant was that afternoon?", "\"No, I do not. I wasn't anywhere near {D.him} that afternoon.\""), .cross("Did the defendant tell you about lending the van before deputies spoke with you?", "\"No. I learned that {DF} said so when the detective called me.\""), .cross("Can anyone confirm where you were at 6:30 p.m. that day?", "\"I live alone, so only my phone and my TV could, and I haven't checked either.\"")],
        theory: ("{D} dragged a woman into a van.", "A coworker with the keys."),
        allocution: "\"I hurt someone and I'm ashamed, and I'm sorry that {V} lived through that. But I did not grab anyone or drag anyone into a van. The van is mine, and I lent it to a coworker that day. I hope the person who did this is found.\"",
        truths: ("The coworker had been out of town that day.", "{DL} was on camera at a hardware store across town at the time of the abduction."),
        defendant: [.direct("Did you take {V}?", "\"No. I did not grab anyone and I did not drag anyone into a van. I would never do something like that.\""), .direct("What about the van?", "\"It is my van, but I lent it to a coworker that day. I believed it was in someone else's hands.\""), .direct("Where were you at 6:30 p.m.?", "\"I was across town, running errands. I did not have my van with me, because I had lent it out.\""), .direct("What kind of work do you do?", "\"I am a maintenance technician at a distribution warehouse, and I use the van to carry tools and parts between sites.\""), .direct("Who had your van that day?", "\"A coworker asked to borrow it that morning to move a few things. I left the keys at work and went home in a ride.\""), .direct("What did you do when deputies came to your door?", "\"I told them the van was mine and that I had lent it out. I gave them the coworker's name and asked them to talk to the coworker.\""), .cross("It's your van, and your plate was written down, isn't that right?", "\"Yes, the van is mine. I can't deny that. But I was not the one driving it that evening.\""), .cross("The coworker denies borrowing it. Why should the jury believe you?", "\"I do not know why the coworker says that. I did lend it, and I'm telling you the truth.\""), .cross("The lineup included you and {V} chose you. How do you explain that?", "\"I think it was unfair. I was the only one who looked a certain way, and I think that made it easy to pick me.\""), .cross("Did the coworker ever give your keys back?", "\"Yes, the next morning, in my mailbox. That's the only reason I know the keys were out of my hands.\""), .cross("Your van, your plate, and a victim who picked you out. What do you say to the jury?", "\"That I understand why it looks like that, and I wasn't there. I would never put my hands on anyone.\"")],
        openings: ("At 6:30 on a weekday evening, someone grabbed {V} in a grocery parking lot and pulled {V.him} into a white van. A witness wrote down the plate, and the van belongs to {D}.", "{D} lent the van to a coworker that day and was across town when this happened. The defense will show a weak lineup and a plate that proves ownership, not who was driving."),
        closings: ("A plate, a van that belongs to {D}, and a victim who picked {DL} from a lineup. The defense can offer a missing coworker, but the van is {D.his} and the plate does not lie.", "Owning a van is not the same as driving it. {V} saw a stranger for seconds, the lineup was unfair, and the coworker is a story the State has not disproved."),
        timeline: [(0, "6:30 p.m.: {V} is pulled into the van."), (0, "6:42 p.m.: {V} jumps out at the light."), (2, "A detective traces the plate."), (5, "{DL} is arrested.")],
        identified: "A witness's plate and a lineup.",
        aggravating: ["The victim was held against their will for a significant period"],
        mood: .wantsConviction,
        impact: "I look at every white van. I can't go to a grocery store without checking the parking lot twice, and I park under a light. I got out at a stoplight half a mile away, and I still hear the door slide shut. I just want to feel safe again.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let festivalOverdose = SmallCases.make(
        key: "story.festivalOverdose",
        category: .drugs,
        headlines: ["Concertgoer Dies After Taking Pill Bought in Parking Lot", "Fentanyl Found in Pills Sold at Music Festival"],
        law: "deathByDistribution",
        threshold: 7,
        spec: "Unlawfully distributed a controlled substance, the ingestion of which caused the death of {V}, on {DATE}.",
        ages: 20...40,
        victim: true,
        summary: "A 19-year-old festival attendee, {V}, collapsed and died after taking a pill bought in a parking lot on {DATE}. Testing found fentanyl. Text messages show {D} arranging the sale. {DL} says {D.he} thought the pills were ordinary and sold them to friends for cost.",
        state: [E(.digital, 3, "Text Messages", "{D} arranges to sell {V} two pills for $20."), E(.forensic, 3, "Toxicology", "Fentanyl in {V}'s blood; the pills contain fentanyl."), E(.document, 1, "Bank Transfer", "$20 sent from {V} to {D}.")],
        defense: [E(.statement, 1, "Believed Ordinary", "{DL} says {D.he} thought the pills were ordinary.")],
        role: "Drug task force agent",
        exam: [.direct("What is your role in this case?", "\"I'm an agent on a multi-agency drug task force. I investigate pills and their distribution, and I worked this case after {V}'s death at the festival.\""), .direct("What happened to {V}?", "\"A 19-year-old, {V} collapsed at the festival around 9 p.m. on {DATE} and died at 11 p.m. at the hospital. {V} had taken a pill bought in a parking lot.\""), .direct("What did toxicology show?", "\"Fentanyl in {V}'s blood. The remaining pills we recovered also tested positive for fentanyl.\""), .direct("How was {D} connected to the sale?", "\"Text messages show {D} arranging to sell {V} two pills for $20. A bank transfer shows $20 sent from {V} to {DL}.\""), .direct("What did you learn about the defendant's supply?", "\"{D.He} bought about 40 pills eight days earlier. {D.He} sold some to friends over that period, and two went to {V}.\""), .direct("What did the defendant say when interviewed?", "\"{DL} said the pills were ordinary and that {D.he} sold them to friends at cost. {DL} didn't say anything about fentanyl.\""), .cross("Isn't it true the texts don't mention fentanyl?", "\"Correct. The messages refer to pills and a price. Nothing in them uses the word.\""), .cross("Did the defendant make a profit?", "\"The price was $20 for two, which {D.he} said was cost. I don't have proof either way of a profit.\""), .cross("Did the pills look like a legitimate tablet?", "\"They were pressed to look like a common tablet, with a marking on them. A buyer could be fooled, and that's common.\""), .cross("Did the defendant take any of the pills?", "\"I don't have evidence that {DL} took them. {DL} said {D.he} hadn't, and a search didn't contradict that.\""), .cross("Did you find a test strip at the defendant's home?", "\"A strip was found, and it showed fentanyl a week earlier. I can't say who used it or whether {D.he} read it.\"")],
        defenseRole: "Defendant's friend",
        defenseExam: [.direct("How do you know {D}?", "\"{D} is a friend of mine. We hang out most weekends, and we were together at festivals this summer.\""), .direct("Did the defendant share pills with you?", "\"Yes, {D.he} gave me a couple at cost. They looked like regular tablets, and I took them without any trouble.\""), .direct("What did the defendant say about the pills?", "\"That they were ordinary and a good price. {D.He} didn't say anything about fentanyl or hard drugs.\""), .direct("What did the pills look like?", "\"Round white tablets with a number on one side. They looked just like something from a drugstore.\""), .direct("How did the defendant react to {V}'s death?", "\"{DF} was crushed. {DF} cried on the phone for an hour and kept saying {D.he} would never have sold them.\""), .direct("Did the defendant ever sell hard drugs to you?", "\"Never. As far as I know, {D.he} doesn't use or sell anything harder than what I've described.\""), .cross("You didn't test your own pills, did you?", "\"No. I never tested them. I took them because I trusted {DF}.\""), .cross("You can't say what was in the pills the defendant sold to {V}?", "\"No. I don't know what was in them. I only know what was in the ones I took, and they didn't make me sick.\""), .cross("You weren't there when the defendant sold to {V}, were you?", "\"I wasn't. I didn't see the sale, so I only know what {DF} told me afterward.\""), .cross("You were friends with the defendant, correct?", "\"Yes, which is why this is hard. I'm telling you what I know without shading it.\""), .cross("Did the defendant ever tell you the price was cost?", "\"Yes, but I can't confirm that. I didn't see any receipt or record.\"")],
        theory: ("{D} sold a fatal pill.", "A seller who did not know what was in it."),
        allocution: "\"I'm sorry for the loss of your child. I bought those pills from someone I knew, and I believed they were ordinary tablets, round with a marking on one side, just like something you'd get at a drugstore. I sold them to friends for what I paid. I had no idea.\"",
        truths: ("A test strip at {DL}'s home showed fentanyl a week earlier.", "The pills carried the markings of a legitimate over-the-counter tablet, which {DL} had no reason to doubt."),
        defendant: [.direct("How did you get the pills?", "\"I bought about 40 from someone I knew. I believed they were ordinary over-the-counter tablets, and they looked like them.\""), .direct("What did the pills look like?", "\"Like a common tablet, round with a marking on one side. They looked exactly like what you'd buy at a drugstore.\""), .direct("Why did you sell to {V}?", "\"{V} asked for two and offered $20, which is what I paid. I wasn't trying to make money.\""), .direct("Did you know about fentanyl?", "\"Not in these pills. I had no idea there was anything dangerous in them, and I'd never have sold them if I did.\""), .direct("How did you feel when you learned {V} had died?", "\"Devastated. I couldn't sleep or eat, and I called a friend and said I couldn't believe it.\""), .direct("What did you tell the agents?", "\"The truth. I said where I bought them and how many I sold, and I told them I didn't know what was in them.\""), .cross("You sold pills in a parking lot to someone you barely knew?", "\"I knew {V} slightly from the festival crowd. I know a parking lot isn't the best place for it.\""), .cross("A test strip at your home showed fentanyl a week before, didn't it?", "\"There was a strip around, but I never used it on those pills. I didn't realize what it meant.\""), .cross("You never looked at what the pills actually contained?", "\"No. I took them at face value because they looked right and the price was low. That was a mistake.\""), .cross("You arranged the sale by text?", "\"Yes, and I sent the address of the lot. I did it quickly and without thinking.\""), .cross("You bought 40 and sold most of them?", "\"I sold some to friends at cost. I didn't keep a count, and I wasn't running a business.\"")],
        openings: ("{V}, a 19-year-old at a festival, collapsed at 9 p.m. and died two hours later after taking a pill bought in a parking lot. Texts show {D} arranging the sale of two pills for $20, a bank transfer confirms it, and toxicology found fentanyl in {V}'s blood.", "{D} believed the pills were ordinary tablets, sold them to friends at cost, and never mentioned or knew about fentanyl. The defense says this is a tragedy, but the State must prove {DL} knew what was in the pills."),
        closings: ("A text, a $20 transfer, two pills, and a death. {D} sold a pill that contained fentanyl to a 19-year-old, and the chain from {D.his} hand to {V}'s blood is unbroken.", "The pills looked like ordinary tablets, the texts never mention fentanyl, and {D} sold at cost to friends. A tragedy is not proof that {D.he} knew what the pills contained."),
        timeline: [(-8, "{DL} buys 40 pills."), (0, "Afternoon: {DL} sells {V} two pills."), (0, "9 p.m.: {V} collapses at the festival."), (0, "11 p.m.: {V} dies."), (6, "{DL} is arrested.")],
        identified: "Text messages and a transfer.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .divided,
        impact: "{V.He} was nineteen, and {V.he} wanted to hear {V.his} favorite band. {V.He} had saved up from a summer job for the ticket and talked about it for months. We drove {V.him} to the gate. The next time we saw {V.him} was at the hospital, and {V.he} never woke up.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let poisonCoffee = SmallCases.make(
        key: "story.poisonCoffee",
        category: .violent,
        headlines: ["Office Worker Hospitalized After Coffee Laced With Antifreeze", "Coworker Charged After Poisoning Probe"],
        law: "attemptedMurder1",
        threshold: 8,
        spec: "Attempted to kill {V} with malice, premeditation, and deliberation by poison, on {DATE}.",
        ages: 26...58,
        victim: true,
        summary: "{V} collapsed at {V.his} desk on {DATE} after drinking coffee from a personal mug. A toxicology test found ethylene glycol. The mug's lid had been tampered with. Camera footage shows {D} leaving the break room with a bottle at 8:10 a.m. {DL} says the bottle was a cleaner and {D.he} had no motive.",
        state: [E(.forensic, 3, "Toxicology", "Ethylene glycol in {V}'s blood and in the mug."), E(.video, 3, "Break Room Camera", "{D} leaves the break room with a bottle at 8:10 a.m."), E(.document, 2, "Email", "{D} wrote that {V}'s promotion was undeserved.")],
        defense: [E(.statement, 1, "Cleaner", "{DL} says the bottle was a window cleaner.")],
        role: "Police detective",
        exam: [.direct("What did the toxicology test show?", "\"{V} collapsed at {V.his} desk after drinking from a personal mug, and the toxicology test found ethylene glycol, which is found in antifreeze.\""), .direct("What does the break room video show?", "\"At 8:10 a.m., {D} leaves the break room carrying a bottle. The mug's lid had been tampered with, according to the lab.\""), .direct("What did you learn about the relationship between {D} and {V}?", "\"I found an email from {DL} complaining about {V}'s promotion. {DL} had applied for the same position.\""), .direct("What led you to the mug?", "\"{V} collapsed at the desk and paramedics took the mug with the coffee for testing. The lid had a tiny puncture and a smear that wasn't consistent with how it was sold.\""), .direct("What did the toxicology report conclude?", "\"Ethylene glycol was found in {V}'s blood and in the coffee remaining in the mug. {V} was treated in time but spent a week in the hospital.\""), .direct("How did you narrow down who might have wanted to hurt {V}?", "\"I interviewed the coworkers who used the break room that morning, and none had a known conflict with {V}. Only {D} had applied for the same promotion.\""), .cross("The bottle was never found, was it?", "\"No. We did not recover it, and I cannot tell you what was in it.\""), .cross("Many people used that break room, didn't they?", "\"Several people did. The video shows other coworkers coming and going before and after {D.him}.\""), .cross("Can you say when the ethylene glycol was put into the mug?", "\"Not precisely. It was before {V} drank it, but I cannot say who had access in the hours before.\""), .cross("Does the camera show the defendant touching the mug?", "\"No. The mug sits on {V}'s desk out of the camera's view, and nothing on that footage shows who handled it.\""), .cross("Did you find ethylene glycol on {D}'s hands or in {D}'s car?", "\"No. We swabbed {D.his} workspace and car and nothing positive came back.\"")],
        defenseRole: "HR manager",
        defenseExam: [.direct("What do you know about the promotion?", "\"{D} applied for the position and was not selected. {V} got it, and I told them both.\""), .direct("How did {D} react?", "\"{D.He} was disappointed and said so to me. {D.He} asked how to improve for next time.\""), .direct("Did the defendant make threats?", "\"No. I never heard any threats from {D.him}. The conversations I had were professional.\""), .direct("What is your role, and how long have you worked with the defendant?", "\"I'm the human resources manager. {D.He} has been here six years, and I handle the reviews and promotions.\""), .direct("What did the defendant's record look like?", "\"Clean. There were no discipline problems and several positive reviews. {D.He} came to HR to ask about the promotion process and stayed professional.\""), .direct("How many people applied for the promotion?", "\"Five. Two were considered finalists, {V} and {DF}, and the decision went to {V}.\""), .cross("Was the defendant angry about it?", "\"Disappointed is the word I would use. I would not say angry, but it was clear {DF} wanted the job.\""), .cross("Did the defendant complain to others?", "\"I know about an email. I did not hear about other complaints, though there could have been some.\""), .cross("Did the defendant and {V} work closely together?", "\"They worked in the same department and saw each other every day. That is all I can say.\""), .cross("Did you see the email the defendant sent about the promotion?", "\"Yes. It was sharp, and I counseled {D.him} about tone, but it didn't contain any threats.\""), .cross("Did the defendant ever express anger toward {V} in person?", "\"Not in front of me. I heard frustration, but no hostility or threats.\"")],
        theory: ("{D} poisoned a rival's coffee.", "A bottle of cleaner and a disappointed coworker."),
        allocution: "\"I never meant it to go that far, and I'm sorry that {V} was hurt. I would never harm anyone. I took a bottle of cleaner from the supply cabinet to wipe up a spill and was returning it. I didn't touch {V.his} mug, and I pray {V.he} recovers.\"",
        truths: ("A jug of antifreeze was in {DL}'s garage with the label scraped.", "The camera clock was a day off."),
        defendant: [.direct("Did you poison {V}'s coffee?", "\"No. I would never harm anyone. I did not touch {V}'s mug, and I did not put anything in it.\""), .direct("What was in the bottle you carried out of the break room?", "\"It was a cleaner. I had taken it from the supply cabinet to wipe up a spill, and I was returning it.\""), .direct("How did you feel about the promotion?", "\"I was frustrated, and I said so in an email. But being upset about a promotion is not a reason to hurt someone.\""), .direct("Explain to the jury how you reacted to the promotion.", "\"I was disappointed and I wrote an email saying so. It was a mistake to put it in writing, but I never wanted to hurt anyone.\""), .direct("When did you first learn {V} was in the hospital?", "\"About an hour later, when the office emptied out. I was horrified and worried for {V.him}.\""), .direct("Do you keep antifreeze at home?", "\"Yes, a jug of it in my garage for my car. Police swabbed my car and my workspace and found nothing, and I never put it near anyone's coffee.\""), .cross("You sent an email complaining about {V}'s promotion, didn't you?", "\"Yes. I was frustrated and I wrote it down. I regret the tone, but I never wanted anyone hurt.\""), .cross("Why would you have antifreeze at home?", "\"It is for my car. Lots of people keep it in a garage for that reason.\""), .cross("The bottle you carried out has never been found. Where is it?", "\"I put it back where it belonged. I don't know what happened to it after that, and I can't prove it.\""), .cross("You called the promotion undeserved. Isn't that motive?", "\"It's a reason to be upset, not a reason to hurt someone. I've worked there for years and I'm not that person.\""), .cross("The mug's lid was tampered with. Who else would have had a reason?", "\"I don't know. The break room is open to everyone, and I wasn't paying attention to who came and went.\"")],
        openings: ("{V} collapsed at a desk after drinking coffee from a personal mug laced with ethylene glycol. The State will show a tampered lid, a bottle carried out of the break room at 8:10, and a recent promotion dispute.", "A cleaning bottle, a disappointed coworker, and a break room used by many people. The defense will show that nothing places poison in {D}'s hands."),
        closings: ("Antifreeze in a mug, a tampered lid, and {D} leaving the room with a bottle on camera. Add the promotion email, and the picture is hard to ignore.", "The State never found the bottle, never showed what was in it, and cannot say who else had access. Disappointment over a job is not evidence of poison."),
        timeline: [(-30, "{V} gets the promotion."), (0, "8:10 a.m.: {DL} leaves the break room with a bottle."), (0, "10 a.m.: {V} collapses."), (2, "Toxicology returns ethylene glycol."), (14, "{DL} is arrested.")],
        identified: "A break room camera.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "My kidneys will never be the same. I took one sip of my usual coffee at my desk and felt a heat in my stomach. The doctors say it was poison. I spent two weeks in the hospital, and now I'm on dialysis three days a week. I don't trust a cup anymore.",
        doctrines: ["burdenOfProof"])

    static let fatalPunchParty = SmallCases.make(
        key: "story.fatalPunchParty",
        category: .violent,
        headlines: ["One Punch at House Party Leaves Man Dead", "Guest Dies After Fall on Concrete Driveway"],
        law: "volManslaughter",
        threshold: 7,
        spec: "Unlawfully killed {V} without malice, premeditation, or deliberation upon a sudden heat of passion, on {DATE}.",
        ages: 19...35,
        victim: true,
        summary: "At a house party on {DATE}, {V} and {D} argued over a spilled drink in the driveway. {DL} punched {V} once, and {V} fell and hit {V.his} head on the concrete. {V} died the next morning. {DL} says {V} threw the first shove and {D.he} never meant to hurt anyone.",
        state: [E(.statement, 3, "Host", "{D} punched {V} once and {V} fell."), E(.forensic, 3, "Autopsy", "Skull fracture consistent with a fall onto concrete."), E(.video, 1, "Phone Video", "{V} shoves {D}, then {D} swings.")],
        defense: [E(.statement, 2, "Friend", "A friend says {V} shoved {D} first."), E(.statement, 1, "Self-Defense", "{DL} says {D.he} reacted to the shove.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you come to this call?", "\"Dispatch sent me to a house party on {DATE} after a 911 call at 10:25 p.m. reporting a person down in a driveway. {V} had a head injury.\""), .direct("What did you find at the scene?", "\"{V} lying on the concrete with a bleeding head wound, being tended by {D}, who was holding a towel to the injury.\""), .direct("What did witnesses tell you?", "\"That {V} and {DL} argued over a spilled drink around 10 p.m. in the driveway. {DL} punched {V} once, and {V} fell and hit the concrete.\""), .direct("What did the phone video show?", "\"{V} shoves {DL}, and then {DL} swings once. The video is short and doesn't show everything before the shove.\""), .direct("What happened to {V}?", "\"{V} was taken to the hospital and died the next morning. The autopsy found a skull fracture consistent with a fall onto concrete.\""), .direct("What did {D} say to you?", "\"{DL} said {V} shoved first and that {DL} swung without thinking. {DL} said {D.he} never meant to hurt anyone.\""), .cross("Isn't it true the video shows {V} shoving first?", "\"Yes. It shows {V} putting hands on {DL} before {DL} swings. It doesn't show what was said beforehand.\""), .cross("Did the defendant throw more than one punch?", "\"No. One punch, and then {V} fell. I saw no further blows from anyone.\""), .cross("Who called 911?", "\"{D.He} called at 10:25, five minutes after the punch. {D.He} stayed on the scene and held a towel to the wound.\""), .cross("Was the defendant intoxicated?", "\"I smelled alcohol on several people at the party, including {DL}. {DL} was steady and coherent when I spoke to {D.him}.\""), .cross("Did the defendant try to leave?", "\"No. {DL} stayed, gave a statement, and helped the paramedics when they arrived.\"")],
        defenseRole: "Defendant's friend",
        defenseExam: [.direct("How do you know {D}?", "\"{D} is a good friend. We've known each other since high school, and I was at the party with {D.him}.\""), .direct("What did you see in the driveway?", "\"I saw {V} and {DF} arguing over a drink. {V} stepped up and shoved {DF} in the chest, and {DF} stumbled back.\""), .direct("What did the defendant do then?", "\"{D.He} swung once. It was quick, like a reflex, and {V} went down and hit the pavement.\""), .direct("What did the defendant do after that?", "\"{DF} ran to {V}, got a towel, and pressed it on the wound. {DF} called 911 and kept talking to {V}.\""), .direct("How did the defendant seem afterward?", "\"Shaken. {D.He} was crying and asked me over and over if {V} would be all right.\""), .direct("Have you seen the defendant in fights before?", "\"Never. {DF} doesn't start fights, and I've known {DF} for years.\""), .cross("You saw the defendant throw the punch, didn't you?", "\"Yes, I saw it. It was one swing, but it landed and {V} fell.\""), .cross("You can't hear what was said before the shove, can you?", "\"No. I was a few feet away, and the music was going. I didn't catch every word.\""), .cross("Did you hear the defendant say anything about money?", "\"I heard something earlier in the evening about a debt, but I don't know the details.\""), .cross("You're the defendant's friend, aren't you?", "\"Yes. I'm trying to say only what I saw, even though I wish it had gone differently.\""), .cross("{V} fell hard, didn't {V}?", "\"Very hard. I heard the impact, and I knew right away it was bad.\"")],
        theory: ("{D} punched a man who then died.", "A shove, one swing, and a call for help."),
        allocution: "\"I wish I could take it back, and I'm sorry. Someone spilled a drink, and we went out to the driveway and it got loud. {V} shoved me in the chest, and I swung without thinking, once. I never meant to hurt anyone. I think about that fall every single night.\"",
        truths: ("{D} had told a friend earlier that {V} owed {D.him}.", "{D} called 911 and held a towel to {V}'s head."),
        defendant: [.direct("What started the argument?", "\"Someone spilled a drink, and {V} thought it was me. We went outside to the driveway and it got loud.\""), .direct("What happened right before you swung?", "\"{V} shoved me hard in the chest. I stumbled back, and I swung without thinking, hitting {V} once.\""), .direct("Did you mean to hurt {V}?", "\"No. I wanted {V} to back off. I never meant for {V} to fall or to be hurt, let alone die.\""), .direct("What did you do after {V} fell?", "\"I grabbed a towel from a friend and held it to the wound. I called 911 and told the dispatcher where we were.\""), .direct("How are you coping with what happened?", "\"Terrible. I think about it every day, and I wish I could take that swing back.\""), .direct("What did you tell the deputies?", "\"Everything. I told them about the shove and the punch, and I said I was sorry.\""), .cross("You punched {V} in the head, didn't you?", "\"Yes, I swung and hit {V}. I'm not going to say I didn't.\""), .cross("{V} owed you money, didn't {V}?", "\"There was something about money earlier, yes. It wasn't what the fight was about, and I didn't bring it up that night.\""), .cross("You'd been drinking?", "\"I'd had a few drinks. I wasn't drunk, but I wasn't as sharp as I should have been.\""), .cross("You could have walked away after the shove?", "\"I could have, and I wish I had. It all happened in a second, and I reacted instead of thinking.\""), .cross("The concrete was hard and you knew it?", "\"I knew we were in a driveway. I didn't think about it when I swung.\"")],
        openings: ("At a house party, {V} and {D} argued over a spilled drink in a driveway at 10 p.m., and {DL} punched {V} once. {V} fell, hit the concrete, and died the next morning, with a skull fracture consistent with that fall.", "{V} shoved {D} first, {DL} swung once in reaction, and {DL} then called 911 and held a towel to the wound. The defense says this was a tragic reaction to a shove, not an intent to kill or seriously injure."),
        closings: ("A punch to the head, a fall onto concrete, and a skull fracture, all following an argument over a drink. {D} swung and {V} died, and the law holds a person responsible for the foreseeable result.", "The video shows {V} shoving first, one swing, and then {D} on the phone with 911 and holding a towel to the wound. This was a moment of reaction, and the State must prove more than a punch."),
        timeline: [(0, "10 p.m.: the argument over a drink."), (0, "10:20 p.m.: the shove, then the punch."), (0, "10:25 p.m.: {DL} calls 911."), (1, "{V} dies at the hospital.")],
        identified: "A host and a phone video.",
        mitigating: ["The defendant acted under strong provocation", "The defendant has accepted responsibility"],
        mood: .divided,
        impact: "We lost our son over a spilled drink. {V.He} was twenty-two, and {V.he} had gone to that party to have fun with friends. We got a call from the hospital the next morning. I keep {V.his} room the way {V.he} left it, with {V.his} boots by the door.",
        doctrines: ["lesserIncluded", "selfDefense"],
        genders: ["D": .male, "V": .male])

    static let wrenchAssault = SmallCases.make(
        key: "story.wrenchAssault",
        category: .violent,
        headlines: ["Mechanic Struck With Wrench in Shop Dispute Over Bill", "Customer Charged After Assault Leaves Man With Fractured Skull"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a wrench, inflicting serious injury, on {DATE}.",
        ages: 24...58,
        victim: true,
        summary: "{V}, a mechanic, was hit in the head with a wrench on {DATE} after a dispute with {D} over a $1,400 repair bill. {V} suffered a fractured skull. {DL} left in a truck. {DL} says {V} lunged first and the wrench was in {D.his} hand from the shop floor.",
        state: [E(.statement, 3, "Shop Employee", "{D} swung the wrench at {V}'s head."), E(.forensic, 2, "Medical Records", "Skull fracture and a laceration."), E(.document, 1, "Repair Invoice", "A disputed $1,400 invoice.")],
        defense: [E(.statement, 1, "Lunged", "{DL} says {V} lunged and {D.he} swung in fear.")],
        role: "Police officer",
        exam: [.direct("What did the employee tell you when you arrived?", "\"The employee said {D} swung a wrench at {V}'s head after an argument. {V} was on the floor, bleeding, and {DL} had already left in a truck.\""), .direct("What injury did {V} suffer?", "\"A fractured skull. {V} was taken to the hospital and was treated for a serious head injury.\""), .direct("What was the argument about?", "\"A $1,400 repair bill. {V}, a mechanic, and {DL} disagreed about the work, and the dispute got heated.\""), .direct("What did you see when you arrived at the shop?", "\"{V} was on the floor of the service bay with blood on the side of the head, conscious but dazed. A wrench lay on the concrete a few feet away.\""), .direct("Who was present when you arrived?", "\"A second employee, who had called 911, and a customer waiting in the lobby. {DL}'s truck had already left, and the employee gave us the plate.\""), .direct("How did you find {D}?", "\"Through the plate and the shop's work order for the repair. We located the truck at {D.his} home about two hours later, and {D.he} came to the door without resistance.\""), .cross("The second employee says {V} raised an arm. Did you hear that?", "\"I did, but the first employee did not see anything like that. The two accounts differ.\""), .cross("Where was the wrench before it was used?", "\"It was on a bench in the shop. I do not know who picked it up, only that it ended up in {D.his} hand.\""), .cross("Did the defendant tell you what happened?", "\"{D.He} later told me {V} lunged first. I noted that, and I took it seriously.\""), .cross("Did you see the swing yourself?", "\"No. I arrived after the fact. What I know about the swing comes from the employees and from {D.him}.\""), .cross("Did you check the defendant for injuries or signs of a struggle?", "\"{D.He} had a scrape on one hand and said it came from the wrench. I did not see other marks.\"")],
        defenseRole: "Second employee",
        defenseExam: [.direct("What did you see in the shop?", "\"I saw {V} raise an arm as the argument got loud. It was quick, and I was not looking right at it the whole time.\""), .direct("What did {V} do with that arm?", "\"It looked like {V} was reaching forward. I thought for a moment that {V} was going to grab something or push.\""), .direct("What happened next?", "\"Everything moved fast. I heard a crack and saw {V} fall, and I ran to help.\""), .direct("What is your job at the shop?", "\"I'm one of the mechanics. I'd been working there about two years and was in the bay next to {V} that morning.\""), .direct("What did you hear before the swing?", "\"Raised voices about the bill. {V} was saying the price had been agreed, and {D} was saying it hadn't.\""), .direct("Where were you standing?", "\"About fifteen feet away, near a lift. Part of my view was blocked by the lift arm.\""), .cross("Was {V} raising an arm at {D}?", "\"It might have been pointing toward the door. I can't say for sure which it was.\""), .cross("How far away were you?", "\"About across the shop floor. I could see them both but not clearly.\""), .cross("Did you see {V} swing at anything?", "\"No. I did not see {V} swing at {DF} or anyone else.\""), .cross("Did you see {V} touch the defendant?", "\"No. I saw {V} move forward, but I can't say whether a hand touched anyone.\""), .cross("Did you see where the wrench came from?", "\"From the bench, I think, but my view wasn't clear and I didn't watch the bench until after the swing.\"")],
        theory: ("{D} hit a mechanic with a wrench over a bill.", "A lunge and a swing in fear."),
        allocution: "\"I'm sorry about what I did to you. We argued over a repair bill, and you lunged at me, and I swung the wrench that was in my hand from the shop floor. I was afraid. I never planned to use it on anyone. I wish I'd walked out of that shop.\"",
        truths: ("{D} had a text to a friend: 'I'm going to fix him.'", "The second employee's view was blocked by a lift."),
        defendant: [.direct("Did you swing the wrench?", "\"Yes, I did. {V} lunged at me during the argument and I swung without thinking. I was afraid.\""), .direct("Why did you pick up the wrench?", "\"It was in my hand from the shop floor when we were arguing. I didn't plan to use it on anyone.\""), .direct("What did you do after?", "\"I panicked and left in my truck. I should have stayed and called for help, and I regret that.\""), .direct("What was the dispute about?", "\"A repair bill of $1,400 for work I didn't think had all been done. I was told the price would be about nine hundred.\""), .direct("Where was the wrench before you picked it up?", "\"On a bench by the bay. I had it in my hand because I was pointing at the engine and wanted to show {V} where I thought the work hadn't been done.\""), .direct("What happened right before you swung?", "\"{V} stepped toward me fast with a hand up. I flinched, my arm came around, and the wrench hit {V.him}.\""), .cross("You hit {V} in the head. Isn't that more than self-defense?", "\"I swung out of fear. I did not aim for the head. I just wanted {V} to stop coming at me.\""), .cross("You left a person with a fractured skull on the floor, didn't you?", "\"I did, and I am not proud of it. I was scared and I did not think clearly.\""), .cross("You were angry about a $1,400 bill, weren't you?", "\"But being upset about money is not the same as wanting to hurt someone.\""), .cross("You were pointing with a wrench. Isn't a wrench a heavy tool to hold during an argument?", "\"It was in my hand and I wasn't thinking about it. I didn't plan to use it on anyone.\""), .cross("After the swing, you walked out and drove away. Why didn't you call 911?", "\"I panicked. I thought I'd done something terrible and I couldn't think. I should have stayed, and I regret that more than anything.\"")],
        openings: ("A mechanic was struck in the head with a wrench after an argument over a $1,400 repair bill, suffering a fractured skull. {D} left in a truck, and the State will show why.", "{D} admits swinging the wrench, but only after {V} lunged. The defense will show a frightened swing in a shop, with no plan to hurt anyone."),
